import { STAGE_LABELS, TERRAIN_TYPES, PROGRAM_TYPES } from './data.js';
import {
  createUniverse,currentAbility,dateFromDay,dayOfYear,directorById,directorHallScore,eventById,eventCategory,hallOfFame,hallScore,
  careerMultiplierForYear,RIDER_SKILL_LABELS,riderById,simulateSeason,simulateWeeks,openNextSeason,teamById,teamHallScore,topRiders,uciRankings,upgradeUniverse
} from './engine.js';
import { deleteUniverse,listUniverses,loadUniverse,saveUniverse } from './storage.js';
import { countryFlag,esc,formatNumber,titleCase } from './utils.js';

const app=typeof document!=='undefined'?document.querySelector('#imperative-app'):null;
let state=null,slot=null,route='results',modal=null,busy=false,toastTimer=null,selectedEventId=null,selectedRaceId=null,selectedRiderId=null,selectedTeamId=null,selectedDirectorId=null,resultsTier='all',resultsType='all',resultsSearch='',almanacTab='riders',magazineTab='preseason',statsEntity='riders',statsMetric='raceWins',statsTier='all',statsScope='season',rankingScope='rolling',rankingTier='all',riderTab='overview',teamTab='overview',directorTab='overview',calendarTier='all',calendarType='all',calendarSearch='',riderTier='all',riderRarity='all',riderProgram='all',riderTerrain='all',riderSearch='',teamTier='all',teamSort='points',teamSearch='',directorTierFilter='all',directorSearch='',navigationStack=[];

if(app)init();
async function init(){renderLoading();try{renderSaveScreen(await listUniverses());}catch(error){console.error(error);app.innerHTML='<div class="loading">IndexedDB could not be opened.</div>';}}
function renderLoading(){app.innerHTML='<div class="loading">Opening the cycling archive…</div>';}
function toast(message){document.querySelector('.toast')?.remove();const node=document.createElement('div');node.className='toast';node.textContent=message;document.body.append(node);clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.remove(),2800);}
async function persist(){if(slot&&state)state=await saveUniverse(slot,state);}
function renderSaveScreen(rows){const bySlot=new Map(rows.map(row=>[row.slot,row]));app.innerHTML=`<main class="save-screen"><section class="save-paper"><header class="save-title"><div class="eyebrow">The international road cycling archive</div><h1>Peloton Chronicle</h1><p>Simulate by week. Follow every career. Preserve every era.</p></header><div class="save-slots">${[1,2,3].map(n=>saveSlot(n,bySlot.get(n))).join('')}</div></section></main>`;}
function saveSlot(number,row){return `<article class="save-slot ${row?'':'empty'}"><div><div class="eyebrow">Archive drawer ${number}</div><h3>${row?esc(row.name):'Empty Chronicle'}</h3>${row?`<p class="muted">Season ${row.year} · Week ${Math.ceil((row.currentDay||1)/7)}</p><small class="muted">Updated ${new Date(row.updatedAt).toLocaleString()}</small>`:'<p class="muted">Create a procedural modern cycling world beginning in 2026.</p>'}</div><div class="top-actions">${row?`<button class="btn" data-load-slot="${number}">Open</button><button class="btn danger" data-delete-slot="${number}">Delete</button>`:`<button class="btn gold" data-new-slot="${number}">Create universe</button>`}</div></article>`;}
async function openSlot(number){busy=true;renderLoading();slot=number;state=upgradeUniverse(await loadUniverse(number));route='results';selectedEventId=latestResult()?.eventId||state.events[0]?.id;busy=false;render();}
async function newSlot(number){const name=window.prompt('Name this cycling universe','Main Chronicle')||'Main Chronicle';slot=number;state=createUniverse({name,seed:Date.now()%2147483647});await persist();route='results';selectedEventId=state.events[0]?.id;render();}

function shell(content){
  const date=dateFromDay(state.year,state.currentDay||1),next=state.events[state.eventIndex],week=Math.ceil((state.currentDay||1)/7),closed=state.seasonStatus==='complete';
  const controls=closed?`<span class="season-closed-label">${state.year} complete</span><button class="btn gold" data-action="open-next-season">Move to ${state.year+1}</button>`:`<button class="btn secondary" data-action="simulate-1">+ 1 week</button><button class="btn secondary" data-action="simulate-4">+ 4 weeks</button><button class="btn gold" data-action="simulate-season">End of year</button>`;
  return `<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-kicker">Cycling history since ${state.archives[0]?.year||state.year}</div><h1>Peloton<br/>Chronicle</h1><p>${esc(state.name)}</p></div><nav class="nav">
  ${navButton('results','Results','▤')}${navButton('calendar','Calendar','▦')}${navButton('races','Races','⚑')}
  <div class="nav-section">The peloton</div>${navButton('riders','Riders','●')}${navButton('teams','Teams','◆')}${navButton('directors','Race Directors','✦')}${navButton('transfers','Market','⇄')}
  <div class="nav-section">History & records</div>${navButton('rankings','UCI Rankings','↕')}${navButton('stats','Statistics','▥')}${navButton('magazine','Le Grand Braquet','✒')}${navButton('almanac','Almanac','▣')}${navButton('hall','Hall of Fame','♜')}
  <div class="nav-section">Universe</div>${navButton('settings','Save & Settings','⚙')}
  </nav><div class="sidebar-footer">WorldTour and ProSeries in full; U23 and continental cycling feed the professional market.</div></aside>
  <main class="main"><header class="topbar"><div class="season-date"><button class="btn secondary menu-btn" data-menu>☰</button><strong>${state.year}</strong><span>${closed?'Season complete · review remains open':`Week ${week} · ${date.label}${next?` · Next: ${esc(next.name)}`:''}`}</span></div><div class="top-actions simulation-actions">${controls}</div></header><div class="content">${content}</div></main></div>${modal?renderModal():''}`;
}
function navButton(id,label,icon){return `<button class="${route===id?'active':''}" data-route="${id}"><span>${icon}</span>${label}</button>`;}
function pageHead(kicker,title,copy,extra=''){return `<header class="page-head"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2><p>${copy}</p></div>${extra||`<div class="date-stamp">Season ${state.year}</div>`}</header>`;}
function pageFor(id){const pages={results:resultsPage,calendar:calendarPage,races:racesPage,'race-detail':raceDetailPage,'rider-detail':riderDetailPage,'team-detail':teamDetailPage,'director-detail':directorDetailPage,riders:ridersPage,teams:teamsPage,directors:directorsPage,transfers:transfersPage,rankings:rankingsPage,stats:statsPage,magazine:magazinePage,almanac:almanacPage,hall:hallPage,settings:settingsPage};return pages[id]||resultsPage;}
function render(){if(!state)return;app.innerHTML=shell(pageFor(route)());}
function navigationSnapshot(){return{route,selectedEventId,selectedRaceId,selectedRiderId,selectedTeamId,selectedDirectorId,riderTab,teamTab,directorTab};}
function navigateDetail(nextRoute,idField,id,tabField=null,tab='overview'){navigationStack.push(navigationSnapshot());if(navigationStack.length>30)navigationStack.shift();route=nextRoute;if(idField==='race')selectedRaceId=id;if(idField==='rider')selectedRiderId=id;if(idField==='team')selectedTeamId=id;if(idField==='director')selectedDirectorId=id;if(tabField==='rider')riderTab=tab;if(tabField==='team')teamTab=tab;if(tabField==='director')directorTab=tab;modal=null;render();}
function restoreNavigation(){const previous=navigationStack.pop();if(!previous){route='results';render();return;}route=previous.route;selectedEventId=previous.selectedEventId;selectedRaceId=previous.selectedRaceId;selectedRiderId=previous.selectedRiderId;selectedTeamId=previous.selectedTeamId;selectedDirectorId=previous.selectedDirectorId;riderTab=previous.riderTab;teamTab=previous.teamTab;directorTab=previous.directorTab;modal=null;render();}
function backControl(fallbackLabel='Back'){return `<button class="btn secondary back-control" data-action="nav-back">← ${fallbackLabel}</button>`;}
export function renderPageForTest(universe,page='results'){state=upgradeUniverse(universe);route=page;selectedEventId=selectedEventId||state.events[0]?.id;selectedRaceId=selectedRaceId||state.events[0]?.id;modal=null;return shell(pageFor(page)());}
export function renderFilteredResultsForTest(universe,{tier='all',type='all',search=''}={}){state=upgradeUniverse(universe);route='results';resultsTier=tier;resultsType=type;resultsSearch=search;selectedEventId=null;modal=null;return shell(resultsPage());}
export function renderRiderPageForTest(universe,riderId,tab='overview'){state=upgradeUniverse(universe);route='rider-detail';selectedRiderId=riderId;riderTab=tab;modal=null;return shell(riderDetailPage());}
export function renderTeamPageForTest(universe,teamId,tab='overview'){state=upgradeUniverse(universe);route='team-detail';selectedTeamId=teamId;teamTab=tab;modal=null;return shell(teamDetailPage());}
export function renderDirectorPageForTest(universe,directorId,tab='overview'){state=upgradeUniverse(universe);route='director-detail';selectedDirectorId=directorId;directorTab=tab;modal=null;return shell(directorDetailPage());}
export function renderRidersForTest(universe,{tier='all',rarity='all',program='all',terrain='all',search=''}={}){state=upgradeUniverse(universe);route='riders';riderTier=tier;riderRarity=rarity;riderProgram=program;riderTerrain=terrain;riderSearch=search;modal=null;return shell(ridersPage());}
export function renderTeamsForTest(universe,{tier='all',sort='points',search=''}={}){state=upgradeUniverse(universe);route='teams';teamTier=tier;teamSort=sort;teamSearch=search;modal=null;return shell(teamsPage());}

function latestResult(){return state?.eventResults?.at(-1)||null;}
function currentResult(eventId){return state.eventResults.find(result=>result.eventId===eventId&&result.year===state.year);}
function teamName(id){if(!id)return'—';return teamById(state,id)?.name||id.replace(/^u23-nation-|^nation-/,'');}
function money(value){const n=Number(value)||0;return n>=1000000?`€${(n/1000000).toFixed(n>=10000000?1:2)}m`:n>=1000?`€${Math.round(n/1000)}k`:`€${Math.round(n)}`;}
function teamStyle(team){const colors=team?.colors||team?.primarySponsor?.colors||['#742d31','#b1842d'];return `--team-primary:${esc(colors[0]||'#742d31')};--team-secondary:${esc(colors[1]||'#b1842d')}`;}
function sponsorMark(sponsor){if(!sponsor)return'<span class="muted">None</span>';const color=sponsor.colors?.[0]||'#742d31';return `<span class="sponsor-mark"><i style="background:${esc(color)}"></i><strong>${esc(sponsor.name)}</strong><small>${titleCase(sponsor.size)} · ${sponsor.money} money · ${sponsor.attraction} attraction</small></span>`;}
function directorName(id){return directorById(state,id)?.name||'Vacant';}
function monthName(month){return ['','January','February','March','April','May','June','July','August','September','October','November','December'][month];}
function formatGap(seconds){const minutes=Math.floor(seconds/60),rest=seconds%60;return minutes?`${minutes}′ ${String(rest).padStart(2,'0')}″`:`${rest}″`;}
function typeLabel(event){return {'grand-tour':'Grand Tour',monument:'Monument','stage-race':'Stage race',classic:'Classic',championship:'Championship'}[eventCategory(event)];}
function tierLabel(tier){return tier==='worldtour'?'WorldTour':tier==='proseries'?'ProSeries':tier==='u23'?'U23':tier==='continental'?'Continental':'National';}
function statValue(book,metric,tier='all'){if(!book)return 0;return tier==='all'?(book[metric]||0):(book.byTier?.[tier]?.[metric]||0);}

function seasonLeaders(){
  const active=state.riders.filter(r=>!r.retired),teams=state.teams.filter(t=>t.status==='active');
  return {wins:[...active].sort((a,b)=>b.currentSeason.raceWins-a.currentSeason.raceWins||b.currentSeason.uciPoints-a.currentSeason.uciPoints)[0],stages:[...active].sort((a,b)=>b.currentSeason.stageWins-a.currentSeason.stageWins)[0],points:[...active].sort((a,b)=>b.currentSeason.uciPoints-a.currentSeason.uciPoints)[0],team:[...teams].sort((a,b)=>b.currentSeason.uciPoints-a.currentSeason.uciPoints)[0]};
}
function filteredResultEvents(){const q=resultsSearch.trim().toLowerCase();return state.events.filter(event=>(resultsTier==='all'||event.tier===resultsTier)&&(resultsType==='all'||eventCategory(event)===resultsType)&&(!q||event.name.toLowerCase().includes(q)));}

function seasonReviewPanel(){if(state.seasonStatus!=='complete'||!state.pendingArchive)return'';const archive=state.pendingArchive,grandTours=['giro','tour','vuelta'].map(id=>({event:eventById(state,id),result:currentResult(id)})).filter(x=>x.event&&x.result);return `<section class="season-review"><header><div><div class="eyebrow">Final issue · December 31</div><h3>${state.year} Season Review</h3><p>The season is closed, not advanced. Browse every ${state.year} result, ranking and career record before opening ${state.year+1}.</p></div><button class="btn gold" data-action="open-next-season">Move to ${state.year+1}</button></header><div class="season-review-leaders"><article><small>World #1</small><button class="entity-link" data-open-rider="${archive.summary.topRider?.id||''}">${esc(archive.summary.topRider?.name||'—')}</button><strong>${formatNumber(archive.summary.topRider?.points||0)} pts</strong></article><article><small>Top team</small><button class="entity-link" data-open-team="${archive.summary.topTeam?.id||''}">${esc(archive.summary.topTeam?.name||'—')}</button><strong>${formatNumber(archive.summary.topTeam?.points||0)} pts</strong></article><article><small>Most race wins</small><button class="entity-link" data-open-rider="${archive.summary.mostWins?.id||''}">${esc(archive.summary.mostWins?.name||'—')}</button><strong>${archive.summary.mostWins?.raceWins||0}</strong></article><article><small>Most stage wins</small><button class="entity-link" data-open-rider="${archive.summary.mostStages?.id||''}">${esc(archive.summary.mostStages?.name||'—')}</button><strong>${archive.summary.mostStages?.stageWins||0}</strong></article></div><div class="grand-tour-review">${grandTours.map(({event,result})=>`<article><span>${countryFlag(event.country)} ${esc(event.name)}</span><button class="entity-link" data-open-rider="${result.winnerId}">${esc(result.winnerName)}</button><small>${esc(teamName(result.winnerTeamId))}</small><div>${result.classification.slice(0,3).map(row=>`<b>#${row.rank} ${esc(row.name)}${row.rank>1?` +${formatGap(row.gap)}`:''}</b>`).join('')}</div><button class="text-action" data-open-race="${event.id}">Full result →</button></article>`).join('')}</div></section>`;}
function rankingMiniTable(rows,entity='rider',limit=5){return `<div class="mini-ranking">${rows.slice(0,limit).map(row=>`<button class="mini-rank-row" data-open-${entity}="${row.id}"><b>${row.rank}</b><span>${countryFlag(row.nationality)} ${esc(row.name)}</span><strong>${formatNumber(row.points)}</strong></button>`).join('')||'<p class="muted">No ranking points yet.</p>'}</div>`;}
function recentRaceCards(){const rows=[...state.eventResults].filter(r=>r.year===state.year).slice(-3).reverse();return rows.length?rows.map(result=>{const event=eventById(state,result.eventId);return `<article class="recent-race-card ${eventCategory(event)}"><div><small>${monthName(result.month)} ${result.day} · ${tierLabel(result.tier)}</small><h4>${countryFlag(event?.country)} ${esc(result.eventName)}</h4></div><button class="entity-link" data-open-rider="${result.winnerId}">${countryFlag(riderById(state,result.winnerId)?.nationality)} ${esc(result.winnerName)}</button><span>${esc(teamName(result.winnerTeamId))}</span><button class="text-action dark" data-open-race="${result.eventId}">Full result →</button></article>`}).join(''):'<p class="muted">No completed races yet.</p>';}
function grandTourHomeCards(){return ['giro','tour','vuelta'].map(id=>{const event=eventById(state,id);if(!event)return'';const result=currentResult(id),favorite=eventFavorites(event,1)[0];if(result){return `<article class="gt-home-card gt-${id} completed"><small>${countryFlag(event.country)} ${esc(event.name)}</small><span>Winner</span><button class="entity-link" data-open-rider="${result.winnerId}">${countryFlag(riderById(state,result.winnerId)?.nationality)} ${esc(result.winnerName)}</button><b>${esc(teamName(result.winnerTeamId))}</b><button class="text-action dark" data-open-race="${id}">Open edition →</button></article>`;}return `<article class="gt-home-card gt-${id}"><small>${countryFlag(event.country)} ${esc(event.name)}</small><span>Current favorite</span><button class="entity-link" data-open-rider="${favorite?.id||''}">${favorite?`${countryFlag(favorite.nationality)} ${esc(favorite.name)}`:'No favorite yet'}</button><b>${favorite?`${currentAbility(favorite).toFixed(1)} form · ${esc(teamName(favorite.teamId))}`:'Start lists pending'}</b><button class="text-action dark" data-open-race="${id}">Race preview →</button></article>`;}).join('');}
function topThreeStat(metric){return state.riders.filter(r=>!r.retired).sort((a,b)=>(b.currentSeason?.[metric]||0)-(a.currentSeason?.[metric]||0)||(b.currentSeason?.uciPoints||0)-(a.currentSeason?.uciPoints||0)).slice(0,3);}
function homeStatList(metric){return `<div class="home-stat-list">${topThreeStat(metric).map((r,i)=>`<button data-open-rider="${r.id}"><b>${i+1}</b><span>${countryFlag(r.nationality)} ${esc(r.name)}</span><strong>${r.currentSeason?.[metric]||0}</strong></button>`).join('')}</div>`;}
function resultsPage(){
  const ranking=uciRankings(state,'rolling'),events=filteredResultEvents();if(!selectedEventId||!events.some(e=>e.id===selectedEventId))selectedEventId=(events.find(e=>currentResult(e.id))||events[0])?.id||null;const selected=eventById(state,selectedEventId),result=selected?currentResult(selected.id):null;
  return `${pageHead('The weekly race desk','Results',state.seasonStatus==='complete'?`${state.year} is complete. Every result remains fully open until you explicitly begin ${state.year+1}.`:'The world at a glance: rankings, recent winners, Grand Tour watch and season leaders before the full race desk.')}
  <section class="chronicle-masthead" role="img" aria-label="Peloton Chronicle, the definitive cycling annual"><span>Season ${state.year}</span></section>
  ${seasonReviewPanel()}
  <div class="home-rankings"><section class="card"><div class="section-title flush"><h3>UCI rider ranking</h3><a data-route="rankings">Top 5 · Rolling 52 weeks</a></div>${rankingMiniTable(ranking.riders,'rider',5)}</section><section class="card"><div class="section-title flush"><h3>UCI team ranking</h3><a data-route="rankings">Top 3 · Rolling 52 weeks</a></div>${rankingMiniTable(ranking.teams,'team',3)}</section></div>
  <div class="section-title"><h3>Latest winners</h3><span>Last three completed races</span></div><div class="recent-races-grid">${recentRaceCards()}</div>
  <div class="section-title"><h3>Grand Tour watch</h3><span>Favorite before the start · winner after the finish</span></div><div class="grand-tour-home-grid">${grandTourHomeCards()}</div>
  <div class="home-leader-grid"><section class="card"><div class="section-title flush"><h3>Most race wins</h3><span>Top 3</span></div>${homeStatList('raceWins')}</section><section class="card"><div class="section-title flush"><h3>Most stage wins</h3><span>Top 3</span></div>${homeStatList('stageWins')}</section></div>
  <div class="section-title"><h3>Browse ${state.year} results</h3><span>Filter every race and inspect the complete edition</span></div>
  <div class="results-browser"><section class="race-index card"><div class="filters compact"><select id="results-tier"><option value="all" ${resultsTier==='all'?'selected':''}>All tiers</option>${tierOptions(true,resultsTier)}</select><select id="results-type"><option value="all" ${resultsType==='all'?'selected':''}>All race types</option>${typeOptions(resultsType)}</select><input id="results-search" value="${esc(resultsSearch)}" placeholder="Search race…"></div><div class="filter-summary">${events.length} matching race${events.length===1?'':'s'}</div><div class="race-index-list" id="results-list">${events.map(event=>resultIndexRow(event,selected?.id)).join('')||'<p class="muted empty-filter">No races match both filters.</p>'}</div></section><section class="result-desk">${selected?(result?resultView(result,selected,true):upcomingRaceView(selected)):'<article class="card"><h3>No matching race</h3><p class="muted">Change one of the filters to reopen the race desk.</p></article>'}</section></div>`;
}
function resultIndexRow(event,selectedId){const result=currentResult(event.id),status=result?`<span class="result-winner">${countryFlag(riderById(state,result.winnerId)?.nationality)} ${esc(result.winnerName)}</span>`:dayOfYear(state.year,event.month,event.day)<state.currentDay?'<span class="muted">No edition</span>':'<span class="muted">Upcoming</span>';return `<button class="race-index-row ${event.id===selectedId?'selected':''}" data-select-result="${event.id}" data-tier="${event.tier}" data-type="${eventCategory(event)}" data-search="${esc(event.name.toLowerCase())}"><span class="race-date">${monthName(event.month).slice(0,3)} ${event.day}</span><span><strong>${countryFlag(event.country)} ${esc(event.name)}</strong><small>${tierLabel(event.tier)} · ${typeLabel(event)}</small>${status}</span><span class="prestige-number">${event.prestige}</span></button>`;}
function upcomingRaceView(event){if(!event)return'';const favorites=eventFavorites(event,6);return `<article class="race-poster ${eventCategory(event)}"><div class="poster-meta">${monthName(event.month)} ${event.day} · ${tierLabel(event.tier)}</div><h3>${countryFlag(event.country)} ${esc(event.name)}</h3><div class="poster-number">${event.prestige}</div><p>${event.stageProfiles.length===1?STAGE_LABELS[event.stageProfiles[0]]:`${event.stageProfiles.length} stages`} · ${typeLabel(event)}</p><div class="section-title light"><h3>Projected favorites</h3></div>${favorites.map((r,i)=>riderLine(r,i+1)).join('')||'<p>No projected start list yet.</p>'}<button class="btn paper" data-open-race="${event.id}">Go to race details</button></article>`;}
function resultView(result,event,showRaceButton=false){
  return `<section class="result-sheet"><div class="race-result-hero ${eventCategory(event)}"><div><div class="eyebrow">Official ${state.year} result · ${tierLabel(result.tier)}</div><h3>${esc(result.eventName)}</h3><p>${countryFlag(riderById(state,result.winnerId)?.nationality)} <button class="entity-link inverted" data-open-rider="${result.winnerId}">${esc(result.winnerName)}</button> · ${esc(teamName(result.winnerTeamId))}</p></div><div class="winner-seal"><span>Winner</span><strong>${result.classification[0]?.rank||1}</strong></div></div>
  <div class="result-columns"><article class="card"><div class="section-title flush"><h3>Final classification</h3><span>Top 10</span></div>${classificationTable(result)}</article><article class="card"><div class="section-title flush"><h3>${result.stages.length>1?'Stages':'Race profile'}</h3><span>${result.stages.length} day${result.stages.length===1?'':'s'}</span></div>${stageList(result)}${result.stages.length>1?jerseysView(result):''}${showRaceButton?`<button class="btn gold full" data-open-race="${result.eventId}">Go to race details & history</button>`:''}</article></div></section>`;
}
function classificationTable(result){return `<div class="table-wrap"><table><thead><tr><th>#</th><th>Rider</th><th>Team</th><th>Gap</th></tr></thead><tbody>${result.classification.slice(0,10).map(row=>`<tr><td class="rank">${row.rank}</td><td><button class="entity-link" data-open-rider="${row.riderId}">${countryFlag(riderById(state,row.riderId)?.nationality)} ${esc(row.name)}</button></td><td>${esc(teamName(row.teamId))}</td><td>${row.rank===1?'Winner':`+${formatGap(row.gap)}`}</td></tr>`).join('')}</tbody></table></div>`;}
function stageList(result){return `<div class="stage-list">${result.stages.map(stage=>`<div class="stage-row"><span class="stage-no">${result.stages.length===1?'Race':`Stage ${stage.number}`}</span><span class="profile-mark ${stage.profile}">${STAGE_LABELS[stage.profile]}</span><button class="entity-link" data-open-rider="${stage.winnerId}">${countryFlag(riderById(state,stage.winnerId)?.nationality)} ${esc(stage.winnerName)}</button><small>${esc(teamName(stage.teamId))}</small></div>`).join('')}</div>`;}
function jerseysView(result){return `<div class="jersey-grid">${jerseyCard('General',result.winnerId,'yellow')}${jerseyCard('Points',result.jerseys.points,'green')}${jerseyCard('Mountains',result.jerseys.mountains,'polka')}${jerseyCard('Young rider',result.jerseys.young,'white')}${teamAwardCard(result.teamClassification)}</div>`;}
function teamAwardCard(teamId){const team=teamById(state,teamId);return team?`<button class="jersey-card team-award" data-open-team="${teamId}"><span class="team-award-icon">◆</span><small>Team classification</small><strong>${esc(team.name)}</strong></button>`:'';}
function jerseyCard(label,id,color){const rider=riderById(state,id);return rider?`<button class="jersey-card ${color}" data-open-rider="${id}"><span class="jersey-icon"></span><small>${label}</small><strong>${esc(rider.name)}</strong></button>`:'';}
function riderLine(rider,rank){return `<button class="entity-link rider-line" data-open-rider="${rider.id}"><span class="rank">${rank}</span><span>${countryFlag(rider.nationality)} <strong>${esc(rider.name)}</strong><small>${esc(teamName(rider.teamId))} · ${titleCase(rider.program)}</small></span><b>${Math.round(currentAbility(rider))}</b></button>`;}
function leaderTable(riders,mode='career'){return `<div class="table-wrap"><table><thead><tr><th>#</th><th>Rider</th><th>Team</th><th>Tier</th><th>Points</th><th>Races</th><th>Stages</th></tr></thead><tbody>${riders.map((r,i)=>{const b=mode==='current'?r.currentSeason:r.career;return `<tr><td class="rank">${i+1}</td><td><button class="entity-link" data-open-rider="${r.id}">${countryFlag(r.nationality)} ${esc(r.name)}</button></td><td>${esc(teamName(r.teamId))}</td><td>${tierLabel(r.tier)}</td><td>${formatNumber(b.uciPoints)}</td><td>${b.raceWins}</td><td>${b.stageWins}</td></tr>`;}).join('')}</tbody></table></div>`;}

function filteredCalendarEvents(){const q=calendarSearch.trim().toLowerCase();return state.events.filter(event=>(calendarTier==='all'||event.tier===calendarTier)&&(calendarType==='all'||eventCategory(event)===calendarType)&&(!q||event.name.toLowerCase().includes(q)));}
function calendarPage(){const events=filteredCalendarEvents();return `${pageHead('Every road on one page','Calendar','The calendar includes WorldTour, ProSeries, U23 and selected continental racing. Filter by tier or race type; weekly simulation resolves everything that falls inside the chosen period.')}
<div class="filters"><select id="calendar-tier"><option value="all" ${calendarTier==='all'?'selected':''}>All tiers</option>${tierOptions(true,calendarTier)}</select><select id="calendar-type"><option value="all" ${calendarType==='all'?'selected':''}>All types</option>${typeOptions(calendarType)}</select><input id="calendar-search" value="${esc(calendarSearch)}" placeholder="Search race…"></div><div class="filter-summary">${events.length} matching race${events.length===1?'':'s'}</div><div class="calendar" id="calendar-list">${events.map(calendarRow).join('')||'<p class="muted empty-filter">No races match these calendar filters.</p>'}</div>`;}
function calendarRow(event){const result=currentResult(event.id),eventDay=dayOfYear(state.year,event.month,event.day),status=result?'Filed':eventDay<=state.currentDay?'Passed':'Ahead';return `<button class="event-row ${event.tier} ${status==='Filed'?'completed':''} ${state.events[state.eventIndex]?.id===event.id?'next':''}" data-open-race="${event.id}" data-tier="${event.tier}" data-type="${eventCategory(event)}" data-search="${esc(event.name.toLowerCase())}"><span class="event-date">${monthName(event.month).slice(0,3)}<br>${event.day}</span><span><strong class="event-name">${countryFlag(event.country)} ${esc(event.name)}</strong><small class="event-meta">${typeLabel(event)} · ${event.stageProfiles.length===1?STAGE_LABELS[event.stageProfiles[0]]:`${event.stageProfiles.length} stages`}</small>${result?`<small class="calendar-winner">${countryFlag(riderById(state,result.winnerId)?.nationality)} ${esc(result.winnerName)}</small>`:''}</span><span class="event-tier"><span class="chip">${tierLabel(event.tier)}</span></span><span class="event-prestige"><span class="prestige"><i style="width:${event.prestige}%"></i></span><small>Prestige ${event.prestige}</small></span><span class="chip ${status==='Filed'?'sage':status==='Ahead'?'wine':'gold'}">${status}</span></button>`;}

function racesPage(){return `${pageHead('Institutions with their own histories','Races','Every race has a permanent page: current edition, complete lineage, greatest winners, stage records, jersey records, prestige changes and status evolution.')}
<div class="filters"><select id="races-tier"><option value="all">All tiers</option>${tierOptions()}</select><select id="races-type"><option value="all">All types</option>${typeOptions()}</select><input id="races-search" placeholder="Search race…"></div><div class="race-card-grid" id="race-card-list">${[...state.events].sort((a,b)=>b.prestige-a.prestige).map(raceCard).join('')}</div>`;}
function raceCard(event){const result=currentResult(event.id),editions=event.editions?.length||0;return `<button class="race-card ${eventCategory(event)}" data-open-race="${event.id}" data-tier="${event.tier}" data-type="${eventCategory(event)}" data-search="${esc(event.name.toLowerCase())}"><div class="race-card-top"><span>${countryFlag(event.country)} <span class="chip">${tierLabel(event.tier)}</span></span><b>${event.prestige}</b></div><h3>${esc(event.name)}</h3><p>${typeLabel(event)} · ${event.stageProfiles.length===1?'One day':`${event.stageProfiles.length} stages`}</p><div class="race-card-winner"><small>${result?'Winner this year':'Current status'}</small><strong>${result?`${countryFlag(riderById(state,result.winnerId)?.nationality)} ${esc(result.winnerName)}`:'Awaiting edition'}</strong></div><footer><span>${editions} edition${editions===1?'':'s'} archived</span><span>Open →</span></footer></button>`;}
function raceDetailPage(){const event=eventById(state,selectedRaceId)||state.events[0],result=currentResult(event.id),editions=[...(event.editions||[])].reverse(),winnerCounts=countBy(editions,e=>e.winnerId,e=>({id:e.winnerId,name:e.winnerName})),stageCounts=countBy(editions.flatMap(e=>e.stageWinners||[]),x=>x.riderId,x=>({id:x.riderId,name:x.name})),jerseyEntries=editions.flatMap(e=>Object.values(e.jerseyWinners||e.jerseys||{}).filter(Boolean).map(value=>typeof value==='object'?value:{id:value,name:riderById(state,value)?.name||value})),jerseyCounts=countBy(jerseyEntries,x=>x.id,x=>x);
  return `${pageHead(`${tierLabel(event.tier)} · Prestige ${event.prestige}`,event.name,`${typeLabel(event)} · ${event.stageProfiles.length===1?STAGE_LABELS[event.stageProfiles[0]]:`${event.stageProfiles.length} stages`}. Race prestige and category can evolve while its lineage remains permanent.`,backControl())}
  <div class="race-detail-banner ${eventCategory(event)}"><div><span>${monthName(event.month)} ${event.day}</span><h3>${countryFlag(event.country)} ${esc(event.name)}</h3><p>${editions.length} archived editions · Founded in the modern Chronicle era</p></div><strong>${event.prestige}</strong></div>
  ${result?resultView(result,event,false):upcomingRaceView(event)}
  <div class="grid cols-3 race-records"><section class="card"><div class="section-title flush"><h3>Most victories</h3></div>${recordList(winnerCounts,5,'wins')}</section><section class="card"><div class="section-title flush"><h3>Most stage wins</h3></div>${recordList(stageCounts,5,'stages')}</section><section class="card"><div class="section-title flush"><h3>Most jerseys</h3></div>${recordList(jerseyCounts,5,'jerseys')}</section></div>
  <div class="grid cols-2 race-history-grid"><section class="card edition-history-card"><div class="section-title flush"><h3>Edition history</h3><span>${editions.length}</span></div>${editions.length?`<div class="table-wrap"><table><thead><tr><th>Year</th><th>GC winner</th><th>Team</th><th>Points</th><th>Mountains</th><th>Young rider</th><th>Stages</th></tr></thead><tbody>${editions.map(e=>`<tr><td>${e.year}</td><td><button class="entity-link" data-open-rider="${e.winnerId}">${countryFlag(riderById(state,e.winnerId)?.nationality)} ${esc(e.winnerName)}</button></td><td>${esc(teamName(e.teamId))}</td><td>${editionJersey(e,'points')}</td><td>${editionJersey(e,'mountains')}</td><td>${editionJersey(e,'young')}</td><td>${e.stageWinners?.length||0}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No edition has been raced yet.</p>'}</section><section class="card"><div class="section-title flush"><h3>Race evolution</h3></div>${event.history?.length?event.history.slice().reverse().map(h=>`<article class="story"><div class="story-category">${h.year}</div><h4>${h.type==='status'?`${tierLabel(h.from)} → ${tierLabel(h.to)}`:titleCase(h.type)}</h4><p>Prestige ${h.prestige||event.prestige}</p></article>`).join(''):'<p class="muted">No category or prestige changes yet.</p>'}</section></div>`;
}
function editionJersey(edition,type){const value=edition.jerseyWinners?.[type]||edition.jerseys?.[type];if(!value)return'—';const id=typeof value==='object'?value.id:value,name=typeof value==='object'?value.name:riderById(state,id)?.name||id;return `<button class="entity-link jersey-history-link" data-open-rider="${id}">${countryFlag(riderById(state,id)?.nationality)} ${esc(name)}</button>`;}
function countBy(items,keyFn,valueFn){const map=new Map();for(const item of items){const key=keyFn(item);if(!key)continue;const entry=map.get(key)||{...valueFn(item),count:0};entry.count++;map.set(key,entry);}return [...map.values()].sort((a,b)=>b.count-a.count);}
function recordList(entries,limit,label){return entries.slice(0,limit).map((e,i)=>`<button class="record-row" data-open-rider="${e.id}"><span class="rank">${i+1}</span><span>${countryFlag(riderById(state,e.id)?.nationality)} <strong>${esc(e.name)}</strong></span><b>${e.count} ${label}</b></button>`).join('')||'<p class="muted">The record book is still empty.</p>';}

function filteredRiders(){const q=riderSearch.trim().toLowerCase();return state.riders.filter(r=>!r.retired&&(riderTier==='all'||r.tier===riderTier)&&(riderRarity==='all'||r.rarity===riderRarity)&&(riderProgram==='all'||r.program===riderProgram)&&(riderTerrain==='all'||r.terrain===riderTerrain)&&(!q||`${r.name} ${r.nationality} ${teamName(r.teamId)}`.toLowerCase().includes(q))).sort((a,b)=>currentAbility(b)-currentAbility(a));}
function ridersPage(){const riders=filteredRiders(),rarityCount=Object.fromEntries(['generational','legend','epic'].map(key=>[key,state.riders.filter(r=>!r.retired&&r.rarity===key).length]));return `${pageHead('Every generation is visible','Riders','WorldTour stars, ProSeries professionals, continental free agents and U23 prospects share one searchable career database.')}<div class="rarity-roster-strip"><span><b>${rarityCount.generational}</b> Generational</span><span><b>${rarityCount.legend}</b> Legends</span><span><b>${rarityCount.epic}</b> Epics</span><small>Elite places are fixed and only reopen when a rider retires.</small></div>${riderFilters()}<div class="filter-summary">${riders.length} matching riders</div><div class="rider-grid" id="rider-list">${riders.map(riderCard).join('')||'<p class="muted empty-filter">No riders match these filters.</p>'}</div>`;}
function riderFilters(){return `<div class="filters filter-toolbar"><input id="rider-search" value="${esc(riderSearch)}" placeholder="Search rider, country or team…"><select id="rider-tier"><option value="all" ${riderTier==='all'?'selected':''}>All tiers</option>${tierOptions(false,riderTier)}</select><select id="rider-rarity"><option value="all" ${riderRarity==='all'?'selected':''}>All rarities</option>${['generational','legend','epic','rare','uncommon','common'].map(x=>`<option value="${x}" ${riderRarity===x?'selected':''}>${titleCase(x)}</option>`).join('')}</select><select id="rider-program"><option value="all" ${riderProgram==='all'?'selected':''}>All race preferences</option>${PROGRAM_TYPES.map(x=>`<option value="${x}" ${riderProgram===x?'selected':''}>${titleCase(x)}</option>`).join('')}</select><select id="rider-terrain"><option value="all" ${riderTerrain==='all'?'selected':''}>All stage profiles</option>${TERRAIN_TYPES.map(x=>`<option value="${x}" ${riderTerrain===x?'selected':''}>${titleCase(x)}</option>`).join('')}</select></div>`;}
function riderCard(r){const team=teamById(state,r.teamId),year=careerYearNumber(r);return `<button class="rider-card rarity-${r.rarity}" style="${teamStyle(team)}" data-open-rider-page="${r.id}"><div class="rider-card-accent"></div><div class="rating">${Math.round(currentAbility(r))}</div><div>${countryFlag(r.nationality)} <span class="rarity ${r.rarity}">${titleCase(r.rarity)}</span></div><h4>${esc(r.name)}</h4><p>${esc(teamName(r.teamId))}</p><div class="chips"><span class="chip ${r.tier==='u23'?'blue':''}">${tierLabel(r.tier)}</span><span class="chip">Age ${r.age}</span><span class="chip career-chip">Y${year}/${r.careerLength}</span></div><div class="mini-stats"><div><strong>${r.currentSeason.raceWins}</strong><span>Races</span></div><div><strong>${r.currentSeason.stageWins}</strong><span>Stages</span></div><div><strong>${formatNumber(r.currentSeason.uciPoints)}</strong><span>Points</span></div></div><footer><span>${titleCase(r.program)}</span><span>${titleCase(r.terrain)}</span></footer></button>`;}
function riderDetailPage(){const rider=riderById(state,selectedRiderId)||state.riders.find(r=>!r.retired)||state.riders[0];if(!rider)return `${pageHead('Career archive','Rider','No rider record is available.')}`;return `${pageHead(`${tierLabel(rider.tier)} · ${titleCase(rider.rarity)}`,rider.name,'Career development, current objectives and a complete competitive archive.',backControl())}<div class="tabbar profile-tabs">${[['overview','Overview'],['season','Current season'],['history','History']].map(([id,label])=>`<button class="${riderTab===id?'active':''}" data-rider-tab="${id}">${label}</button>`).join('')}</div>${riderProfileContent(rider,true,riderTab)}`;}
function riderSeasonRecords(r){const archived=[...(r.career.seasons||[])],hasCurrent=archived.some(x=>x.year===state.year);if(!hasCurrent)archived.push({year:state.year,teamId:r.teamId,teamName:teamName(r.teamId),tier:r.tier,...seasonBookSnapshot(r.currentSeason),grandTourResults:r.currentSeason.grandTourResults,current:true});return archived.sort((a,b)=>b.year-a.year);}
function seasonBookSnapshot(book){return{points:book.uciPoints,raceWins:book.raceWins,stageWins:book.stageWins,grandTours:book.grandTours,monuments:book.monuments,weeklong:book.weeklong,classics:book.classics,jerseys:book.jerseys,raceDays:book.raceDays,raceWinDetails:book.raceWinDetails||[],stageWinDetails:book.stageWinDetails||[],jerseyWinDetails:book.jerseyWinDetails||[],stageWinsByProfile:book.stageWinsByProfile||{},uciPointDetails:book.uciPointDetails||[]};}
function detailCounts(items,keyFn,labelFn){const map=new Map();for(const item of items||[]){const key=keyFn(item),entry=map.get(key)||{count:0,label:labelFn(item)};entry.count++;map.set(key,entry);}return [...map.values()].map(x=>`${x.label}${x.count>1?` (×${x.count})`:''}`).join('; ')||'—';}
function seasonRaceSummary(season){return detailCounts(season.raceWinDetails,x=>x.eventId,x=>x.event);}
function seasonStageSummary(season){const grouped=new Map();for(const item of season.stageWinDetails||[]){const key=item.profile,group=grouped.get(key)||[];group.push(item);grouped.set(key,group);}return [...grouped.entries()].map(([profile,items])=>`<strong>${titleCase(STAGE_LABELS[profile]?.replace(' stage','')||profile)} ×${items.length}</strong> — ${detailCounts(items,x=>x.eventId,x=>x.event)}`).join('<br>')||'—';}
function jerseyTypeLabel(type){return type==='mountains'?'Mountains':type==='points'?'Points':type==='young'?'Young rider':titleCase(type);}
function seasonJerseySummary(season){const grouped=new Map();for(const item of season.jerseyWinDetails||[]){const rows=grouped.get(item.type)||[];rows.push(item);grouped.set(item.type,rows);}return [...grouped.entries()].map(([type,items])=>`<strong>${jerseyTypeLabel(type)} ×${items.length}</strong> — ${detailCounts(items,x=>x.eventId,x=>x.event)}`).join('<br>')||'—';}
function seasonPointSummary(season){const rows=[...(season.uciPointDetails||[])].sort((a,b)=>(b.points||0)-(a.points||0));if(!rows.length)return season.points?`${formatNumber(season.points)} season points`:'—';return rows.slice(0,8).map(row=>`<strong>${esc(row.event)}</strong> — ${formatNumber(row.points)} pts`).join('<br>');}
function careerYearNumber(r){return Math.max(1,state.year-(r.debutYear||state.year)+1);}
function riderRecentLoad(r,window=28){const cutoff=(state.currentDay||1)-window;return (r.raceLoadLog||[]).filter(row=>row.year===state.year&&row.end>=cutoff).reduce((sum,row)=>sum+(row.days||1),0);}
function fatigueLabel(value){return value>=76?'Exhausted':value>=60?'Heavy':value>=40?'Accumulating':value>=20?'Manageable':'Fresh';}
function shapeLabel(value){return value>=80?'Peak':value>=65?'Race ready':value>=48?'Building':value>=30?'Low':'Cold';}
function developmentTimeline(r){const year=careerYearNumber(r),start=Math.max(1,year-3),end=Math.min(r.careerLength,year+4);return `<div class="development-timeline">${Array.from({length:end-start+1},(_,i)=>start+i).map(y=>{const calendarYear=(r.debutYear||state.year)+y-1,factor=careerMultiplierForYear(r,calendarYear);return `<span class="${y===year?'active':''}"><b>Y${y}</b><small>${factor.toFixed(2)}</small></span>`;}).join('')}</div>`;}
function riderSkillGrid(r){return `<div class="rider-skill-grid">${Object.entries(RIDER_SKILL_LABELS).map(([key,label])=>{const value=Math.round(r.skills?.[key]??currentAbility(r));return `<div class="rider-skill"><span>${label}</span><strong>${value}</strong><i><b style="width:${value}%"></b></i></div>`;}).join('')}</div>`;}
function riderEventPoints(riderId,eventId,year=state.year){return (state.uciPointEvents||[]).filter(row=>row.year===year&&row.riderId===riderId&&row.eventId===eventId).reduce((sum,row)=>sum+(row.points||0),0);}
function riderSeasonProgramme(r){const ids=new Set(r.targetEvents||[]);for(const result of state.eventResults||[])if(result.year===state.year&&result.participantIds?.includes(r.id))ids.add(result.eventId);return [...ids].map(id=>eventById(state,id)).filter(Boolean).sort((a,b)=>(a.month-b.month)||(a.day-b.day));}
function targetResult(r,event){const result=currentResult(event.id);if(!result)return '<span class="result-status upcoming">Not disputed</span>';if(Array.isArray(result.teams)&&!result.teams.includes(r.teamId))return '<span class="result-status unavailable">Team not invited</span>';if(Array.isArray(result.participantIds)&&!result.participantIds.includes(r.id))return '<span class="result-status unavailable">Not selected</span>';const row=result.classification?.find(x=>x.id===r.id||x.riderId===r.id),stages=(result.stages||[]).filter(x=>x.winnerId===r.id||x.riderId===r.id).length,hasStages=(result.stages?.length||event.stageProfiles?.length||0)>1,points=riderEventPoints(r.id,event.id),jerseys=Object.entries(result.jerseys||{}).filter(([,id])=>id===r.id).map(([type])=>jerseyTypeLabel(type));const parts=[row?row.rank===1?'Winner':`Position ${row.rank}`:'Finished outside top 20'];if(hasStages)parts.push(`${stages} stage${stages===1?'':'s'}`);if(jerseys.length)parts.push(jerseys.join(' + '));if(points)parts.push(`${formatNumber(points)} pts`);return `<strong class="result-status placed">${parts.join(' · ')}</strong>`;}
function riderHistorySummary(r){const wins=r.career.raceWinDetails||[],stages=r.career.stageWinDetails||[];const groups=[['WorldTour · Grand Tours',x=>x.tier==='worldtour'&&x.kind==='grand-tour'],['WorldTour · Monuments',x=>x.tier==='worldtour'&&x.kind==='monument'],['WorldTour · Other',x=>x.tier==='worldtour'&&!['grand-tour','monument'].includes(x.kind)],['ProSeries',x=>x.tier==='proseries'],['Continental',x=>x.tier==='continental'],['U23',x=>x.tier==='u23']];return `<div class="table-wrap"><table><thead><tr><th>Level</th><th>Races</th><th>Stages</th></tr></thead><tbody>${groups.map(([label,test])=>`<tr><td>${label}</td><td>${wins.filter(test).length}</td><td>${stages.filter(test).length}</td></tr>`).join('')}</tbody></table></div>`;}
function riderProfileContent(r,full=false,tab='overview'){const targets=riderSeasonProgramme(r),seasons=riderSeasonRecords(r),team=teamById(state,r.teamId),hero=`<div class="profile-hero team-colored rarity-${r.rarity}" style="${teamStyle(team)}"><div><span class="rarity ${r.rarity}">${titleCase(r.rarity)}</span><h2>${countryFlag(r.nationality)} ${esc(r.name)}</h2><p>${team?`<button class="entity-link team-inline-link" data-open-team="${team.id}">${esc(team.name)}</button>`:'No team'} · ${tierLabel(r.tier)} · Age ${r.age} · Career Y${careerYearNumber(r)}/${r.careerLength}</p><div class="chips"><span class="chip wine">Race: ${titleCase(r.program)}</span><span class="chip gold">Stage: ${titleCase(r.terrain)}</span><span class="chip blue">${titleCase(r.developmentProfile)}</span></div></div><div class="profile-rating"><small>Now</small>${Math.round(currentAbility(r))}</div></div>`;
if(tab==='season'){const ordered=[...targets].sort((a,b)=>(a.month-b.month)||(a.day-b.day));const groups=ordered.reduce((map,event)=>{const key=event.month;(map[key]??=[]).push(event);return map;},{});let counter=0;const starts=(state.eventResults||[]).filter(result=>result.year===state.year&&result.participantIds?.includes(r.id)).length,load=riderRecentLoad(r),restDays=Math.max(0,Math.round((r.mandatoryRestUntil||0)-(state.currentDay||1)));return `${hero}<div class="condition-ribbon"><div><span>Race shape</span><strong>${Math.round(r.raceShape||0)}</strong><small>${shapeLabel(r.raceShape||0)}</small></div><div class="${(r.fatigue||0)>=60?'warning':''}"><span>Fatigue</span><strong>${Math.round(r.fatigue||0)}</strong><small>${fatigueLabel(r.fatigue||0)}</small></div><div><span>Last 28 days</span><strong>${load}</strong><small>race days</small></div><div><span>Recovery status</span><strong>${restDays?`${restDays}d`:'Ready'}</strong><small>${restDays?'mandatory rest remaining':'available for selection'}</small></div></div><section class="card season-programme-card"><div class="section-title flush"><h3>${state.year} programme & official results</h3><span>${starts} starts · ${r.currentSeason.raceDays} race days · ${formatNumber(r.currentSeason.uciPoints)} UCI points</span></div><p class="programme-note">Completed races are taken from the official result ledger. Upcoming rows are the protected calendar plan; fatigue, recovery and team selection can still remove a rider from an event.</p><div class="season-plan-months">${Object.entries(groups).map(([month,events])=>`<section class="season-plan-month"><h4>${monthName(Number(month))}</h4><div class="target-result-list">${events.map(e=>{counter+=1;const result=currentResult(e.id),actual=result?.participantIds?.includes(r.id),targeted=(r.targetEvents||[]).includes(e.id);return `<article class="${actual?'official-start':''}"><b>${counter}</b><span>${countryFlag(e.country)} <button class="entity-link" data-open-race="${e.id}">${esc(e.name)}</button><small>${monthName(e.month)} ${e.day} · ${tierLabel(e.tier)} · ${actual?'Official start':targeted?'Planned target':'Schedule'}</small></span>${targetResult(r,e)}</article>`;}).join('')}</div></section>`).join('')||'<p class="muted">No race targets assigned.</p>'}</div></section>`;}
if(tab==='history')return `${hero}<div class="section-title"><h3>Career by competition level</h3></div>${riderHistorySummary(r)}<div class="grid cols-2"><section class="card flat"><div class="section-title flush"><h3>Stages won by type</h3></div>${stageProfileBreakdown(r.career.stageWinsByProfile)}</section><section class="card flat"><div class="section-title flush"><h3>Career totals</h3></div><div class="honor-grid compact">${honor('Grand Tours',r.career.grandTours)}${honor('Monuments',r.career.monuments)}${honor('Races',r.career.raceWins)}${honor('Stages',r.career.stageWins)}${honor('Jerseys',r.career.jerseys)}${honor('UCI points',formatNumber(r.career.uciPoints))}</div></section></div><div class="section-title"><h3>Complete year breakdown</h3><span>Every official win and jersey</span></div><div class="career-season-list">${seasons.map(s=>`<article class="career-season-card ${s.current?'current-season-card':''}"><header><div><strong>${s.year}</strong><span>${esc(s.teamName||teamName(s.teamId))} · ${tierLabel(s.tier)}</span></div><div>${formatNumber(s.points||0)} pts · ${s.raceDays||0} race days</div></header><div class="career-season-summary"><div><b>Races ${s.raceWins||0}</b><p>${seasonRaceSummary(s)}</p></div><div><b>Stages ${s.stageWins||0}</b><p>${seasonStageSummary(s)}</p></div><div><b>Jerseys ${s.jerseys||0}</b><p>${seasonJerseySummary(s)}</p></div><div><b>UCI points ${formatNumber(s.points||0)}</b><p>${seasonPointSummary(s)}</p></div></div><footer>${(s.grandTourResults||[]).map(g=>`${esc(g.event)} #${g.rank}`).join(' · ')||'No Grand Tour top-ten result'} · ${s.grandTours||0} GT · ${s.monuments||0} monuments · ${s.weeklong||0} week-long</footer></article>`).join('')}</div>`;
return `${hero}<div class="grid cols-4 profile-kpis"><article class="card flat kpi"><span>Base skill</span><strong>${r.baseSkill}</strong><small>Fixed from spawn to retirement</small></article><article class="card flat kpi"><span>Annual factor</span><strong>${(r.annualMultiplier||1).toFixed(2)}</strong><small>Career curve × yearly shape</small></article><article class="card flat kpi"><span>Season ceiling</span><strong>${Math.round((r.baseSkill||0)*(r.annualMultiplier||1))}</strong><small>100% in specialist skills</small></article><article class="card flat kpi"><span>Current rating</span><strong>${Math.round(currentAbility(r))}</strong><small>Average after specialty scaling</small></article><article class="card flat kpi"><span>Race shape</span><strong>${Math.round(r.raceShape||0)}</strong><small>${shapeLabel(r.raceShape||0)}</small></article><article class="card flat kpi ${(r.fatigue||0)>=60?'condition-warning':''}"><span>Fatigue</span><strong>${Math.round(r.fatigue||0)}</strong><small>${fatigueLabel(r.fatigue||0)} · ${riderRecentLoad(r)} days in last 28</small></article><article class="card flat kpi"><span>Career year</span><strong>Y${careerYearNumber(r)}/${r.careerLength}</strong><small>${titleCase(r.developmentProfile)}</small></article><article class="card flat kpi"><span>Career wins</span><strong>${r.career.raceWins} / ${r.career.stageWins}</strong><small>races / stages</small></article></div><section class="card flat"><div class="section-title flush"><h3>Rider skills</h3><span>${titleCase(r.terrain)} profile · ${r.terrain==='all-rounder'?'95% across every skill':'100% core · 90% secondary'} · average ${Math.round(currentAbility(r))}</span></div>${riderSkillGrid(r)}</section><section class="card flat"><div class="section-title flush"><h3>Annual development curve</h3><span>Base ${r.baseSkill} × career factor sets the specialist ceiling</span></div>${developmentTimeline(r)}</section><div class="section-title"><h3>Career honors</h3></div><div class="honor-grid">${honor('Grand Tours',r.career.grandTours)}${honor('Monuments',r.career.monuments)}${honor('Week-long races',r.career.weeklong)}${honor('Classics',r.career.classics)}${honor('Race wins',r.career.raceWins)}${honor('Stage wins',r.career.stageWins)}${honor('Jerseys',r.career.jerseys)}${honor('World points',formatNumber(r.career.uciPoints))}</div>`;}

function teamSeasonRecords(t){const archived=[...(t.career.seasons||[])],hasCurrent=archived.some(x=>x.year===state.year);if(!hasCurrent)archived.push({year:state.year,name:t.name,tier:t.tier,directorId:t.directorId,...seasonBookSnapshot(t.currentSeason),current:true});return archived.sort((a,b)=>b.year-a.year);}
function directorSeasonRecords(d){const archived=[...(d.career.seasons||[])],hasCurrent=archived.some(x=>x.year===state.year),team=teamById(state,d.teamId);if(!hasCurrent)archived.push({year:state.year,teamId:d.teamId,teamName:team?.name||'Agency market',tier:team?.tier||'agency',...seasonBookSnapshot(d.currentSeason),current:true});return archived.sort((a,b)=>b.year-a.year);}
function appointmentTierLabel(tier){return tier==='agency'?'Agency':tierLabel(tier);}
function organizationSeasonCards(seasons,entity='team'){return `<div class="career-season-list">${seasons.map(s=>`<article class="career-season-card ${s.current?'current-season-card':''}"><header><div><strong>${s.year}</strong><span>${entity==='team'?`${esc(s.name||'Team identity')} · ${tierLabel(s.tier)}`:`${esc(s.teamName||teamName(s.teamId))} · ${appointmentTierLabel(s.tier)}`}</span></div><div>${formatNumber(s.points||0)} pts · ${s.raceDays||0} race days</div></header><div class="career-season-summary"><div><b>Races ${s.raceWins||0}</b><p>${seasonRaceSummary(s)}</p></div><div><b>Stages ${s.stageWins||0}</b><p>${seasonStageSummary(s)}</p></div><div><b>Jerseys ${s.jerseys||0}</b><p>${seasonJerseySummary(s)}</p></div></div><footer>${s.grandTours||0} Grand Tours · ${s.monuments||0} Monuments · ${s.weeklong||0} week-long races · ${s.classics||0} classics</footer></article>`).join('')}</div>`;}
function teamDetailPage(){const team=teamById(state,selectedTeamId)||state.teams.find(t=>t.status==='active')||state.teams[0];if(!team)return `${pageHead('Organization archive','Team','No team record is available.')}`;return `${pageHead(`${tierLabel(team.tier)} · ${esc(team.identity)}`,team.name,'Current performance and the complete organization history beneath every sponsor identity.',backControl())}<div class="tabbar profile-tabs">${[['overview','Overview'],['season','Current season'],['history','History']].map(([id,label])=>`<button class="${teamTab===id?'active':''}" data-team-tab="${id}">${label}</button>`).join('')}</div>${teamTab==='history'?organizationSeasonCards(teamSeasonRecords(team),'team'):teamTab==='season'?organizationSeasonCards(teamSeasonRecords(team).filter(x=>x.current||x.year===state.year),'team'):teamProfileContent(team,false)}`;}
function directorDetailPage(){const director=directorById(state,selectedDirectorId)||state.directors.find(d=>!d.retired)||state.directors[0];if(!director)return `${pageHead('Director archive','Race Director','No director record is available.')}`;return `${pageHead(`${titleCase(director.rarity)} · Ability ${director.ability}`,director.name,'Current appointment, strategic profile and a full career history.',backControl())}<div class="tabbar profile-tabs">${[['overview','Overview'],['season','Current season'],['history','History']].map(([id,label])=>`<button class="${directorTab===id?'active':''}" data-director-tab="${id}">${label}</button>`).join('')}</div>${directorTab==='history'?organizationSeasonCards(directorSeasonRecords(director),'director'):directorTab==='season'?organizationSeasonCards(directorSeasonRecords(director).filter(x=>x.current||x.year===state.year),'director'):directorProfileContent(director,false)}`;}
function financeRow(label,value,note=''){return `<div class="finance-row"><span>${label}${note?`<small>${esc(note)}</small>`:''}</span><strong>${money(value)}</strong></div>`;}
function teamProfileContent(t,full=false){const roster=t.roster.map(id=>riderById(state,id)).filter(Boolean).sort((a,b)=>currentAbility(b)-currentAbility(a)),d=directorById(state,t.directorId),seasons=teamSeasonRecords(t),f=t.finances||{},payroll=roster.reduce((sum,r)=>sum+(r.salary||0),0);return `<div class="profile-hero team-colored" style="${teamStyle(t)}"><div><span class="chip ${t.tier==='worldtour'?'wine':t.tier==='u23'?'blue':'gold'}">${tierLabel(t.tier)}</span><h2>${countryFlag(t.nationality)} ${esc(t.name)}</h2><p>Permanent organization: <strong>${esc(t.identity)}</strong> · ${t.status==='active'?tierLabel(t.tier):'Inactive organization'}</p><p>Race director: ${d?`<button class="entity-link" data-open-director="${d.id}">${countryFlag(d.nationality)} ${esc(d.name)}</button>`:'Vacant'}</p></div><div class="profile-rating"><small>Rep.</small>${t.reputation}</div></div>
<div class="grid cols-4 profile-kpis">${honorCard('Budget',t.budget,'Commercial strength')}${honorCard('Facilities',Number(t.facilities||0).toFixed(1),'Training level / 10')}${honorCard('Season points',formatNumber(t.currentSeason.uciPoints),`${t.currentSeason.raceWins} race wins`)}${honorCard('Attraction',t.attraction,'Recruitment power')}</div>
<div class="grid cols-2 team-business-grid"><section class="card sponsor-panel" style="${teamStyle(t)}"><div class="section-title flush"><h3>Sponsor portfolio</h3><span>Team colors follow the jersey</span></div><div class="sponsor-pair"><div><small>Primary · team name</small>${sponsorMark(t.primarySponsor)}</div><div><small>Secondary · maillot</small>${sponsorMark(t.secondarySponsor)}</div></div></section><section class="card finance-panel"><div class="section-title flush"><h3>${state.year} finances</h3><span>Income and committed expenses</span></div>${financeRow('Primary sponsor',f.primaryIncome,t.primarySponsor?.name)}${financeRow('Secondary sponsor',f.secondaryIncome,t.secondarySponsor?.name)}${financeRow('Prize money',f.prizeMoney,'Results earned')}${financeRow('Rider salaries',-(f.salaries||payroll),`${roster.length} riders`)}${financeRow('Director salary',-(f.directorSalary||d?.salary||0),d?.name||'Vacant')}${financeRow('Facilities investment',-(f.facilityInvestment||0),`Level ${Number(t.facilities||0).toFixed(1)}`)}<div class="finance-total"><span>Projected balance</span><strong>${money(f.balance??((f.annualIncome||0)-payroll-(d?.salary||0)))}</strong></div></section></div>
<div class="section-title"><h3>Organization honors</h3></div><div class="honor-grid">${honor('Grand Tours',t.career.grandTours)}${honor('Monuments',t.career.monuments)}${honor('Week-long races',t.career.weeklong)}${honor('Classics',t.career.classics)}${honor('Race wins',t.career.raceWins)}${honor('Stage wins',t.career.stageWins)}${honor('Jerseys',t.career.jerseys)}${honor('Hall score',formatNumber(teamHallScore(t)))}</div>
${full?`<div class="section-title"><h3>Complete team year breakdown</h3><span>Every race and jersey won</span></div>${organizationSeasonCards(seasons,'team')}`:''}
<div class="grid cols-2"><section class="card flat"><div class="section-title flush"><h3>Sponsor history</h3></div>${t.history.filter(x=>x.type==='sponsor').slice().reverse().map(x=>`<article class="story"><div class="story-category">${x.year} · ${titleCase(x.role||'primary')}</div><h4>${esc(x.next||x.primary||x.name)}</h4>${x.previous?`<p>Replaced ${esc(x.previous)}.</p>`:''}${x.secondary?`<p>Secondary: ${esc(x.secondary)}</p>`:''}</article>`).join('')||'<p class="muted">No sponsor changes yet.</p>'}</section><section class="card flat"><div class="section-title flush"><h3>Current leadership</h3></div><p>${d?`${countryFlag(d.nationality)} <strong>${esc(d.name)}</strong><br>${d.ability} ability · ${titleCase(d.rarity)} · ${money(d.salary)} salary · ${d.contractYears||0} years left`:'No appointed director.'}</p><p>${t.currentSeason.raceWins} races · ${t.currentSeason.stageWins} stages · ${t.currentSeason.jerseys} jerseys in ${state.year}.</p></section></div>
<div class="section-title"><h3>Current roster</h3><span>${roster.length} riders · ${money(payroll)} payroll</span></div><div class="table-wrap"><table><thead><tr><th>Rider</th><th>Career</th><th>Age</th><th>Role</th><th>Race preference</th><th>Current</th><th>Base skill</th><th>Salary</th><th>Happy</th></tr></thead><tbody>${roster.map(r=>`<tr><td><button class="entity-link" data-open-rider="${r.id}">${countryFlag(r.nationality)} ${esc(r.name)}</button></td><td>Y${careerYearNumber(r)}/${r.careerLength}</td><td>${r.age}</td><td>${r.role}</td><td>${titleCase(r.program)}</td><td>${Math.round(currentAbility(r))}</td><td>${r.potential}</td><td>${money(r.salary)}</td><td>${Math.round(r.happiness||0)}</td></tr>`).join('')}</tbody></table></div>`;}
function directorProfileContent(d,full=false){const team=teamById(state,d.teamId),agency=state.directorAgencies.find(a=>a.id===d.agencyId),seasons=directorSeasonRecords(d);return `<div class="profile-hero ${team?'team-colored':''}" style="${teamStyle(team)}"><div><span class="rarity ${d.rarity}">${titleCase(d.rarity)}</span><h2>${countryFlag(d.nationality)} ${esc(d.name)}</h2><p>${team?`<button class="entity-link" data-open-team="${team.id}">${esc(team.name)}</button>`:d.retired?'Retired':esc(agency?.name||'Agency market')} · Age ${d.age}</p><div class="chips"><span class="chip">${money(d.salary)} salary</span><span class="chip">${d.contractYears||0} years left</span><span class="chip ${d.happiness>=70?'sage':d.happiness<50?'wine':'gold'}">Happiness ${Math.round(d.happiness||0)}</span></div></div><div class="profile-rating"><small>Ability</small>${d.ability}</div></div>
<div class="director-skills large"><span>Tactics <b>${d.tactics}</b></span><span>Development <b>${d.development}</b></span><span>Scouting <b>${d.scouting}</b></span><span>Recruitment <b>${d.recruitment}</b></span></div>
<div class="section-title"><h3>Career honors</h3></div><div class="honor-grid">${honor('Grand Tours',d.career.grandTours)}${honor('Monuments',d.career.monuments)}${honor('Week-long races',d.career.weeklong)}${honor('Race wins',d.career.raceWins)}${honor('Stage wins',d.career.stageWins)}${honor('Jerseys',d.career.jerseys)}${honor('Seasons',d.career.seasonCount)}${honor('Hall score',formatNumber(directorHallScore(d)))}</div>
${full?`<div class="section-title"><h3>Complete director year breakdown</h3><span>Exact wins under every appointment</span></div>${organizationSeasonCards(seasons,'director')}`:''}<div class="section-title"><h3>Career log</h3></div>${[...d.history].reverse().map(h=>`<article class="story"><div class="story-category">${h.year}</div><h4>${esc(h.text)}</h4></article>`).join('')}`;}

function filteredTeams(){const q=teamSearch.trim().toLowerCase(),rank={worldtour:4,proseries:3,u23:2,continental:1};const value=(team)=>teamSort==='budget'?team.budget:teamSort==='points'?team.currentSeason.uciPoints:teamSort==='facilities'?team.facilities:teamSort==='attraction'?team.attraction:teamSort==='director'?(directorById(state,team.directorId)?.ability||0):team.reputation;return state.teams.filter(t=>t.status==='active'&&(teamTier==='all'||t.tier===teamTier)&&(!q||`${t.name} ${t.identity} ${t.primarySponsor?.name||''} ${t.secondarySponsor?.name||''}`.toLowerCase().includes(q))).sort((a,b)=>value(b)-value(a)||(rank[b.tier]||0)-(rank[a.tier]||0));}
function teamsPage(){const teams=filteredTeams();return `${pageHead('Organizations outlive their jerseys','Teams','Primary and secondary sponsors fund the team, define its jersey colors and shape its capacity to retain riders, hire directors and invest in facilities.')}<div class="filters filter-toolbar"><input id="team-search" value="${esc(teamSearch)}" placeholder="Search team, organization or sponsor…"><select id="team-tier"><option value="all" ${teamTier==='all'?'selected':''}>All tiers</option>${tierOptions(false,teamTier)}</select><select id="team-sort"><option value="points" ${teamSort==='points'?'selected':''}>Sort: season points</option><option value="budget" ${teamSort==='budget'?'selected':''}>Sort: budget</option><option value="facilities" ${teamSort==='facilities'?'selected':''}>Sort: facilities</option><option value="attraction" ${teamSort==='attraction'?'selected':''}>Sort: attraction</option><option value="reputation" ${teamSort==='reputation'?'selected':''}>Sort: reputation</option><option value="director" ${teamSort==='director'?'selected':''}>Sort: director ability</option></select></div><div class="filter-summary">${teams.length} matching teams</div><div class="team-grid" id="team-list">${teams.map(teamCard).join('')||'<p class="muted empty-filter">No teams match these filters.</p>'}</div>`;}
function teamCard(t){const d=directorById(state,t.directorId),f=t.finances||{};return `<button class="team-card team-colored tier-${t.tier}" style="${teamStyle(t)}" data-open-team-page="${t.id}"><div class="team-card-accent"></div><div class="team-card-head"><span>${countryFlag(t.nationality)} <span class="chip ${t.tier==='worldtour'?'wine':t.tier==='u23'?'blue':'gold'}">${tierLabel(t.tier)}</span></span><strong>${formatNumber(t.currentSeason.uciPoints)}</strong></div><h4>${esc(t.name)}</h4><p>${esc(t.identity)}</p><div class="team-sponsor-mini"><span><small>Primary</small>${esc(t.primarySponsor?.name||'—')}</span><span><small>Secondary</small>${esc(t.secondarySponsor?.name||'—')}</span></div><div class="sponsor-band"><small>Race director</small><b>${d?`${countryFlag(d.nationality)} ${esc(d.name)} · ${d.ability}`:'Vacant'}</b></div><div class="mini-stats"><div><strong>${t.budget}</strong><span>Budget</span></div><div><strong>${Number(t.facilities||0).toFixed(1)}</strong><span>Facilities</span></div><div><strong>${t.attraction}</strong><span>Attraction</span></div></div><footer><span>${money(f.annualIncome||0)} income</span><span>${t.currentSeason.raceWins} wins</span><span>Rep. ${t.reputation}</span></footer></button>`;}

function filteredDirectors(){const q=directorSearch.trim().toLowerCase();return state.directors.filter(d=>!d.retired&&(directorTierFilter==='all'||directorTier(d)===directorTierFilter)&&(!q||`${d.name} ${teamName(d.teamId)}`.toLowerCase().includes(q))).sort((a,b)=>b.ability-a.ability);}
function directorsPage(){const directors=filteredDirectors();return `${pageHead('The strategists behind the dynasties','Race Directors','Contracts, salaries, happiness and a two-year movement lock create a separate director market. Elite directors should rise toward teams able to support their ambition.')}<div class="filters filter-toolbar"><input id="director-search" value="${esc(directorSearch)}" placeholder="Search director or team…"><select id="director-tier"><option value="all" ${directorTierFilter==='all'?'selected':''}>All appointments</option><option value="agency" ${directorTierFilter==='agency'?'selected':''}>Agencies</option>${tierOptions(false,directorTierFilter)}</select></div><div class="filter-summary">${directors.length} matching directors</div><div class="director-grid" id="director-list">${directors.map(directorCard).join('')||'<p class="muted empty-filter">No directors match these filters.</p>'}</div>`;}
function directorTier(d){return d.teamId?(teamById(state,d.teamId)?.tier||'agency'):'agency';}
function directorCard(d){const team=teamById(state,d.teamId),agency=state.directorAgencies.find(a=>a.id===d.agencyId);return `<button class="director-card ${team?'team-colored':''} rarity-${d.rarity} tier-${team?.tier||'agency'}" style="${teamStyle(team)}" data-open-director-page="${d.id}"><div class="rating">${d.ability}</div><div>${countryFlag(d.nationality)} <span class="rarity ${d.rarity}">${titleCase(d.rarity)}</span></div><h4>${esc(d.name)}</h4><p>${team?esc(team.name):esc(agency?.name||'Independent')}</p><div class="chips"><span class="chip">${money(d.salary)}</span><span class="chip">${d.contractYears||0}y left</span><span class="chip ${d.happiness>=70?'sage':d.happiness<50?'wine':'gold'}">Happy ${Math.round(d.happiness||0)}</span></div><div class="director-skills"><span>TAC <b>${d.tactics}</b></span><span>DEV <b>${d.development}</b></span><span>SCT <b>${d.scouting}</b></span><span>REC <b>${d.recruitment}</b></span></div><div class="mini-stats"><div><strong>${d.career.grandTours}</strong><span>Grand Tours</span></div><div><strong>${d.career.monuments}</strong><span>Monuments</span></div><div><strong>${d.career.raceWins}</strong><span>Wins</span></div></div></button>`;}

function transferReason(m){if(m.reason)return m.reason;if(m.type==='poached')return'Richer project met salary and sporting ambitions';if(m.type==='promotion')return'Elite scouting identified a rider ready for a higher tier';if(m.type==='free-agent')return'Contract expired and the rider entered the open market';return'Contract, happiness and sporting ambition drove the move';}
function transfersPage(){const year=state.year,elite=['generational','legend','epic'],eliteMoves=state.transfers.filter(m=>m.year===year&&elite.includes(m.rarity)),otherMoves=state.transfers.filter(m=>m.year===year&&!elite.includes(m.rarity)),directorMoves=state.directorMoves.filter(m=>m.year===year),sponsors=state.sponsorLog.filter(m=>m.year===year),tiers=state.tierChanges.filter(m=>m.year===year);return `${pageHead('The business of the peloton','The Market','A complete offseason ledger: rider contracts, director appointments, sponsor portfolios, facilities, finances and changes of competitive licence.')}<div class="market-summary grid cols-4"><div class="metric-card"><span>Elite rider moves</span><strong>${eliteMoves.length}</strong><small>Selective, not a yearly exodus</small></div><div class="metric-card"><span>Director changes</span><strong>${directorMoves.length}</strong><small>Two-year movement lock</small></div><div class="metric-card"><span>Sponsor changes</span><strong>${sponsors.length}</strong><small>Primary and secondary</small></div><div class="metric-card"><span>Tier changes</span><strong>${tiers.length}</strong><small>Promotion and relegation</small></div></div><section class="card market-feature"><div class="section-title flush"><h3>Headline rider moves</h3><span>Generational · Legend · Epic</span></div>${marketTable(eliteMoves,'rider',true)}</section><div class="grid cols-2 market-columns"><section class="card"><div class="section-title flush"><h3>Director market</h3><span>Salary · happiness · results</span></div>${marketTable(directorMoves,'director',true)}</section><section class="card"><div class="section-title flush"><h3>Professional rider market</h3><span>Selected notable moves</span></div>${marketTable(otherMoves,'rider',false)}</section></div><div class="grid cols-2 market-columns"><section class="card"><div class="section-title flush"><h3>Sponsor portfolio changes</h3><span>Commercial identity</span></div>${sponsorChangeList(sponsors)}</section><section class="card"><div class="section-title flush"><h3>Licence movement</h3><span>Sporting and financial merit</span></div>${tierChangeList(tiers)}</section></div>`;}
function sponsorChangeList(rows){return rows.length?`<div class="market-list">${rows.map(change=>`<article class="market-card sponsor-change"><div class="market-year">${change.year}</div><div class="market-person"><button class="entity-link" data-open-team="${change.teamId}">${esc(change.identity)}</button><span class="chip">${titleCase(change.role||'primary')}</span></div><div class="market-route"><span>${esc(change.previous)}</span><b>→</b><span>${esc(change.next)}</span></div><small>${change.nextMoney||0} money · ${tierLabel(change.tier)}</small></article>`).join('')}</div>`:'<p class="muted">No sponsor changed this preseason.</p>';}
function tierChangeList(rows){const rank={worldtour:4,proseries:3,continental:2,u23:1},direction=change=>(rank[change.to]||0)>(rank[change.from]||0)?'up':'down';return rows.length?`<div class="market-list licence-list">${rows.map(change=>{const move=direction(change),label=move==='up'?'PROMOTED':'RELEGATED';return `<article class="market-card licence-change ${move}"><div class="market-year">${change.year}</div><div class="market-person"><button class="entity-link" data-open-team="${change.teamId}">${esc(change.teamName)}</button><span>${esc(change.identity)}</span></div><div class="market-route"><span>${tierLabel(change.from)}</span><b>→</b><span>${tierLabel(change.to)}</span></div><span class="licence-direction ${move}">${move==='up'?'↑':'↓'} ${label}</span><small>${esc(change.reason)}</small></article>`;}).join('')}</div>`:'<p class="muted">No licence changed hands this preseason.</p>';}
function marketTable(rows,type,featured=false){if(!rows.length)return'<p class="muted">No notable movement in this window.</p>';return `<div class="market-list ${featured?'featured':''}">${rows.slice(0,60).map(m=>{const isRider=type==='rider',person=isRider?riderById(state,m.riderId):directorById(state,m.directorId),from=m.fromName||teamName(m.from),to=m.toName||teamName(m.to),meta=isRider?`${titleCase(m.rarity||person?.rarity||'')} · Rating ${m.rating||Math.round(currentAbility(person)||0)} · ${money(m.salary||person?.salary||0)}`:`${titleCase(m.rarity||person?.rarity||'')} · Ability ${m.ability||person?.ability||'—'} · ${money(m.salary||person?.salary||0)}`;return `<article class="market-card"><div class="market-year">${m.year}</div><div class="market-person"><button class="entity-link" data-open-${type}="${isRider?m.riderId:m.directorId}">${countryFlag(person?.nationality)} ${esc(isRider?m.riderName:m.directorName)}</button><span class="rarity ${m.rarity||person?.rarity||''}">${esc(meta)}</span></div><div class="market-route"><span>${esc(from)}</span><b>→</b><span>${esc(to)}</span></div><small>${esc(isRider?transferReason(m):(m.reason||'New appointment'))}</small></article>`;}).join('')}</div>`;}

function rankingsPage(){const ranking=uciRankings(state,rankingScope),rolling=rankingScope==='rolling',riders=ranking.riders.filter(x=>rankingTier==='all'||x.tier===rankingTier),teams=ranking.teams.filter(x=>rankingTier==='all'||x.tier===rankingTier);return `${pageHead('Official-style points table','UCI Rankings',rolling?'A rolling 52-week ranking: points expire one year after the result.':'All points earned during the current calendar season.',`<div class="date-stamp">${rolling?'Rolling 52 weeks':`Season ${state.year}`}</div>`)}
<div class="ranking-toolbar"><div class="tabbar ranking-tabs"><button class="${rolling?'active':''}" data-ranking-scope="rolling">Rolling 52 weeks</button><button class="${!rolling?'active':''}" data-ranking-scope="year">Current year</button></div><select id="ranking-tier"><option value="all">All tiers</option>${tierOptions(false,rankingTier)}</select></div>
<div class="ranking-note"><strong>Tier filter uses the rider or team’s current competitive level.</strong><span>Tour GC: 1,300 · Giro/Vuelta GC: 1,100 · Monument: 800 · Tour stage: 210.</span></div>
<div class="grid cols-2 ranking-grid"><section class="card"><div class="section-title flush"><h3>Individual ranking</h3><span>Top 50</span></div>${uciRiderTable(riders.slice(0,50))}</section><section class="card"><div class="section-title flush"><h3>Team ranking</h3><span>Best 20 riders</span></div>${uciTeamTable(teams.slice(0,30))}</section></div>`;}

function uciRiderTable(rows){return `<div class="table-wrap"><table><thead><tr><th>#</th><th>Rider</th><th>Team</th><th>Tier</th><th>UCI pts</th></tr></thead><tbody>${rows.map(row=>`<tr><td class="rank">${row.rank}</td><td><button class="entity-link" data-open-rider="${row.id}">${countryFlag(row.nationality)} ${esc(row.name)}</button></td><td>${esc(teamName(row.teamId))}</td><td>${tierLabel(row.tier)}</td><td><strong>${formatNumber(row.points)}</strong></td></tr>`).join('')}</tbody></table></div>`;}
function uciTeamTable(rows){return `<div class="table-wrap"><table><thead><tr><th>#</th><th>Team</th><th>Tier</th><th>UCI pts</th></tr></thead><tbody>${rows.map(row=>`<tr><td class="rank">${row.rank}</td><td><button class="entity-link" data-open-team="${row.id}">${countryFlag(row.nationality)} ${esc(row.name)}</button></td><td>${tierLabel(row.tier)}</td><td><strong>${formatNumber(row.points)}</strong></td></tr>`).join('')}</tbody></table></div>`;}

function statsPage(){const rows=statRows();return `${pageHead('Compare careers across every level','Statistics','Rank riders, directors or teams by the competitions they won. Tier filters measure where the victories occurred—not simply the current category of the person or team.')}
<div class="stats-controls"><div class="tabbar entity-tabs">${['riders','directors','teams'].map(x=>`<button class="${statsEntity===x?'active':''}" data-stats-entity="${x}">${titleCase(x)}</button>`).join('')}</div><select id="stats-scope"><option value="season" ${statsScope==='season'?'selected':''}>Season ${state.year}</option><option value="career" ${statsScope==='career'?'selected':''}>All-time career</option></select><select id="stats-metric">${metricOptions()}</select><select id="stats-tier"><option value="all" ${statsTier==='all'?'selected':''}>All tiers</option>${tierOptions(true,statsTier)}</select></div>
<div class="table-wrap stats-table"><table><thead><tr><th>#</th><th>${statsEntity==='teams'?'Team':statsEntity==='directors'?'Director':'Rider'}</th><th>Current home</th><th>Career years</th><th>${metricName(statsMetric)}</th><th>Grand Tours</th><th>Monuments</th><th>Stages</th></tr></thead><tbody>${rows.slice(0,100).map((row,i)=>statsRow(row,i)).join('')}</tbody></table></div>`;}
function metricOptions(){return [['grandTours','Grand Tours won'],['monuments','Monuments won'],['weeklong','Week-long races won'],['raceWins','Total races won'],['stageWins','Stages won'],['classics','Classics won'],['championships','Championships won'],['jerseys','Jerseys won']].map(([v,l])=>`<option value="${v}" ${statsMetric===v?'selected':''}>${l}</option>`).join('');}
function metricName(metric){return {grandTours:'Grand Tours',monuments:'Monuments',weeklong:'Week-long races',raceWins:'Race wins',stageWins:'Stage wins',classics:'Classics',championships:'Championships',jerseys:'Jerseys'}[metric];}
function statRows(){const source=statsEntity==='riders'?state.riders:statsEntity==='directors'?state.directors:state.teams;return source.filter(x=>statsEntity==='teams'||x.career?.seasonCount>0||!x.retired).map(x=>{const book=statsScope==='season'?x.currentSeason:x.career;return{entity:x,book,value:statValue(book,statsMetric,statsTier)};}).sort((a,b)=>b.value-a.value||statValue(b.book,'uciPoints',statsTier)-statValue(a.book,'uciPoints',statsTier));}
function statsRow(row,index){const x=row.entity,b=row.book;if(statsEntity==='riders')return `<tr><td class="rank">${index+1}</td><td><button class="entity-link" data-open-rider="${x.id}">${countryFlag(x.nationality)} ${esc(x.name)}</button></td><td>${esc(teamName(x.teamId))}</td><td>${x.career.seasonCount}</td><td><strong>${row.value}</strong></td><td>${statValue(b,'grandTours',statsTier)}</td><td>${statValue(b,'monuments',statsTier)}</td><td>${statValue(b,'stageWins',statsTier)}</td></tr>`;if(statsEntity==='directors')return `<tr><td class="rank">${index+1}</td><td><button class="entity-link" data-open-director="${x.id}">${countryFlag(x.nationality)} ${esc(x.name)}</button></td><td>${x.teamId?esc(teamName(x.teamId)):'Agency'}</td><td>${x.career.seasonCount}</td><td><strong>${row.value}</strong></td><td>${statValue(b,'grandTours',statsTier)}</td><td>${statValue(b,'monuments',statsTier)}</td><td>${statValue(b,'stageWins',statsTier)}</td></tr>`;return `<tr><td class="rank">${index+1}</td><td><button class="entity-link" data-open-team="${x.id}">${countryFlag(x.nationality)} ${esc(x.name)}</button></td><td>${x.status==='inactive'?'Inactive':tierLabel(x.tier)}</td><td>${x.career.seasonCount}</td><td><strong>${row.value}</strong></td><td>${statValue(b,'grandTours',statsTier)}</td><td>${statValue(b,'monuments',statsTier)}</td><td>${statValue(b,'stageWins',statsTier)}</td></tr>`;}

function magazinePage(){return `${pageHead('A historical cycling annual','Le Grand Braquet','A distinctive season magazine with pre-season odds, signings and favorites; live reporting during the year; and a permanent post-season review.')}
<div class="magazine-cover"><div><span>Le Grand Braquet</span><h3>${state.year} Cycling Annual</h3><p>Routes · Rivals · Dynasties · New generations</p></div><b>${state.year}</b></div><div class="tabbar">${[['preseason','Pre-season'],['season','Current season'],['postseason','Post-season'],['archive','Archive']].map(([id,label])=>`<button class="${magazineTab===id?'active':''}" data-mag-tab="${id}">${label}</button>`).join('')}</div>${magazineContent()}`;}
function magazineContent(){if(magazineTab==='preseason')return preseasonMagazine();if(magazineTab==='postseason')return postseasonMagazine();if(magazineTab==='archive')return `<section class="card magazine-columns">${state.news.filter(n=>n.year<state.year).map(storyCard).join('')||'<p class="muted">Earlier editions will collect here.</p>'}</section>`;return `<section class="card magazine-columns">${state.news.filter(n=>n.phase==='season'&&n.year===state.year).map(storyCard).join('')||'<p class="muted">Simulate the opening weeks to publish race reports.</p>'}</section>`;}
function preseasonMagazine(){const tour=eventById(state,'tour'),giro=eventById(state,'giro'),flanders=eventById(state,'flanders'),favorites=[['Tour de France',tour],['Giro d’Italia',giro],['Tour of Flanders',flanders]].filter(x=>x[1]),elite=['generational','legend','epic'],signings=state.transfers.filter(t=>t.year===state.year&&elite.includes(t.rarity)).slice(0,12),prospects=(state.prospectSpawns||[]).filter(x=>x.year===state.year&&elite.includes(x.rarity)),retirements=(state.retirements||[]).filter(x=>x.year===state.year&&elite.includes(x.rarity)).slice(0,12),directors=(state.directorMoves||[]).filter(x=>x.year===state.year).slice(0,12),sponsors=(state.sponsorLog||[]).filter(x=>x.year===state.year).slice(0,12),tiers=(state.tierChanges||[]).filter(x=>x.year===state.year);return `<div class="grid cols-2 preseason-grid"><section class="card"><div class="section-title flush"><h3>Championship odds</h3></div>${favorites.map(([name,event])=>`<article class="odds-block"><h4>${name}</h4>${eventFavorites(event,5).map((r,i)=>`<div><span>${i+1}</span><button class="entity-link" data-open-rider="${r.id}">${countryFlag(r.nationality)} ${esc(r.name)}</button><b>${Math.max(5,Math.round(42-i*7-currentAbility(r)/8))}%</b></div>`).join('')}</article>`).join('')}</section><section class="card"><div class="section-title flush"><h3>Elite signings</h3><span>Only the major moves</span></div>${eliteSigningList(signings)}<div class="section-title"><h3>New elite prospects</h3><span>Vacancies in the elite pool</span></div>${eliteProspectList(prospects)}</section></div><div class="grid cols-2 preseason-grid"><section class="card"><div class="section-title flush"><h3>Retirements</h3><span>Top careers leaving the road</span></div>${retirementList(retirements)}<div class="section-title"><h3>Director appointments</h3><span>Performance reviews and poaching</span></div>${marketTable(directors,'director',false)}</section><section class="card"><div class="section-title flush"><h3>Teams in transition</h3><span>Sponsors and licences</span></div>${sponsorChangeList(sponsors)}<div class="section-title"><h3>Promotion & relegation</h3></div>${tierChangeList(tiers)}</section></div>`;}
function retirementList(rows){if(!rows.length)return'<p class="muted">No elite retirement in this offseason.</p>';return `<div class="elite-market-list">${rows.map(x=>`<article class="elite-market-row"><button class="entity-link" data-open-rider="${x.riderId}">${countryFlag(x.nationality)} <strong>${esc(x.riderName)}</strong></button><span class="rarity ${x.rarity}">${titleCase(x.rarity)}</span><div>Age ${x.age} · ${x.grandTours||0} GT · ${x.monuments||0} monuments</div><small>${x.raceWins||0} races · ${x.stageWins||0} stages</small></article>`).join('')}</div>`;}
function eliteSigningList(rows){if(!rows.length)return'<p class="muted">No elite rider changed teams in this winter window.</p>';return `<div class="elite-market-list">${rows.map(t=>`<article class="elite-market-row"><button class="entity-link" data-open-rider="${t.riderId}">${countryFlag(riderById(state,t.riderId)?.nationality)} <strong>${esc(t.riderName)}</strong></button><span class="rarity ${t.rarity}">${titleCase(t.rarity)}</span><div>${t.rating} rating · ${t.age} yo · ${money(t.salary||riderById(state,t.riderId)?.salary||0)}${t.lastYearRank?` · last year #${t.lastYearRank}`:''}</div><small>${esc(t.fromName||teamName(t.from))} (${tierLabel(t.fromTier)}) → ${esc(t.toName||teamName(t.to))} (${tierLabel(t.toTier)}) · ${esc(transferReason(t))}</small></article>`).join('')}</div>`;}
function eliteProspectList(rows){if(!rows.length)return'<p class="muted">No generational, legend or epic vacancy opened in this U23 class.</p>';return `<div class="elite-market-list">${rows.map(x=>`<article class="elite-market-row"><button class="entity-link" data-open-rider="${x.riderId}">${countryFlag(x.nationality)} <strong>${esc(x.riderName)}</strong></button><span class="rarity ${x.rarity}">${titleCase(x.rarity)}</span><div>${x.rating} current · ${x.potential} base skill · age ${x.age}</div><small>${esc(x.teamName||teamName(x.teamId))} · ${tierLabel('u23')}</small></article>`).join('')}</div>`;}
function postseasonMagazine(){const archive=state.pendingArchive||state.archives.at(-1);if(!archive)return'<article class="card"><h3>No completed season yet</h3><p class="muted">The post-season annual appears after the first year closes.</p></article>';return `<div class="grid cols-2"><section class="card"><div class="section-title flush"><h3>${archive.year} review</h3></div><article class="story lead"><div class="story-category">World number one</div><h4>${esc(archive.summary.topRider?.name||'—')}</h4><p>${archive.headline}</p></article><article class="story"><div class="story-category">Best team</div><h4>${esc(archive.summary.topTeam?.name||'—')}</h4><p>${formatNumber(archive.summary.topTeam?.points||0)} points.</p></article><article class="story"><div class="story-category">Most race wins</div><h4>${esc(archive.summary.mostWins?.name||'—')}</h4><p>${archive.summary.mostWins?.raceWins||0} victories.</p></article><article class="story"><div class="story-category">Most stage wins</div><h4>${esc(archive.summary.mostStages?.name||'—')}</h4><p>${archive.summary.mostStages?.stageWins||0} stages.</p></article></section><section class="card"><div class="section-title flush"><h3>Final top ten</h3></div>${archive.riderRanking.slice(0,10).map((r,i)=>`<div class="record-row"><span class="rank">${i+1}</span><span>${countryFlag(riderById(state,r.id)?.nationality)} <strong>${esc(r.name)}</strong><small>${esc(teamName(r.teamId))}</small></span><b>${formatNumber(r.points)}</b></div>`).join('')}</section></div>`;}
function storyCard(story){const riders=(story.riderIds||[]).map(id=>riderById(state,id)).filter(Boolean);return `<article class="story ${story.importance||''}"><div class="story-category">${esc(story.category)} · ${story.year}</div><h4>${esc(story.headline)}</h4><p>${esc(story.body)}</p>${riders.length?`<div class="story-riders">${riders.map(r=>`<button class="entity-link" data-open-rider="${r.id}">${countryFlag(r.nationality)} ${esc(r.name)}</button>`).join('')}</div>`:''}</article>`;}
function almanacPage(){return `${pageHead('The complete tabular archive','Almanac','The almanac is the exhaustive database: riders, teams, directors and season tables. The Hall of Fame is reserved for shorter, curated lists of greatness.')}
<div class="tabbar">${[['riders','Riders'],['teams','Teams'],['directors','Directors'],['seasons','Seasons']].map(([id,label])=>`<button class="${almanacTab===id?'active':''}" data-almanac-tab="${id}">${label}</button>`).join('')}</div>${almanacContent()}`;}
function almanacContent(){if(almanacTab==='teams')return almanacTeams();if(almanacTab==='directors')return almanacDirectors();if(almanacTab==='seasons')return almanacSeasons();return almanacRiders();}
function almanacRiders(){const riders=[...state.riders].sort((a,b)=>hallScore(b)-hallScore(a));return `<div class="table-wrap"><table><thead><tr><th>Rider</th><th>Nationality</th><th>Years</th><th>Status</th><th>Grand Tours</th><th>Monuments</th><th>Races</th><th>Stages</th><th>Points</th></tr></thead><tbody>${riders.slice(0,1000).map(r=>`<tr><td><button class="entity-link" data-open-rider="${r.id}">${countryFlag(r.nationality)} ${esc(r.name)}</button></td><td>${r.nationality}</td><td>${r.career.seasonCount}</td><td>${r.retired?'Retired':tierLabel(r.tier)}</td><td>${r.career.grandTours}</td><td>${r.career.monuments}</td><td>${r.career.raceWins}</td><td>${r.career.stageWins}</td><td>${formatNumber(r.career.uciPoints)}</td></tr>`).join('')}</tbody></table></div>`;}
function almanacTeams(){const teams=[...state.teams].sort((a,b)=>teamHallScore(b)-teamHallScore(a));return `<div class="table-wrap"><table><thead><tr><th>Organization / current sponsor</th><th>Status</th><th>Tier</th><th>Director</th><th>Seasons</th><th>Grand Tours</th><th>Monuments</th><th>Races</th><th>Stages</th></tr></thead><tbody>${teams.map(t=>`<tr><td><button class="entity-link" data-open-team="${t.id}">${countryFlag(t.nationality)} ${esc(t.name)}</button><small class="muted block">${esc(t.identity)}</small></td><td>${titleCase(t.status)}</td><td>${tierLabel(t.tier)}</td><td>${esc(directorName(t.directorId))}</td><td>${t.career.seasonCount}</td><td>${t.career.grandTours}</td><td>${t.career.monuments}</td><td>${t.career.raceWins}</td><td>${t.career.stageWins}</td></tr>`).join('')}</tbody></table></div>`;}
function almanacDirectors(){const directors=[...state.directors].sort((a,b)=>directorHallScore(b)-directorHallScore(a));return `<div class="table-wrap"><table><thead><tr><th>Director</th><th>Current appointment</th><th>Ability</th><th>Seasons</th><th>Grand Tours</th><th>Monuments</th><th>Races</th><th>Stages</th></tr></thead><tbody>${directors.map(d=>`<tr><td><button class="entity-link" data-open-director="${d.id}">${countryFlag(d.nationality)} ${esc(d.name)}</button></td><td>${d.teamId?esc(teamName(d.teamId)):d.retired?'Retired':'Agency'}</td><td>${d.ability}</td><td>${d.career.seasonCount}</td><td>${d.career.grandTours}</td><td>${d.career.monuments}</td><td>${d.career.raceWins}</td><td>${d.career.stageWins}</td></tr>`).join('')}</tbody></table></div>`;}
function almanacSeasons(){const riderLink=x=>x?.id?`<button class="entity-link" data-open-rider="${x.id}">${esc(x.name)}</button>`:esc(x?.name||'—'),gt=(a,id)=>{const x=(a.raceWinners||[]).find(r=>r.eventId===id);return x?`<button class="entity-link" data-open-rider="${x.winnerId}">${esc(x.winnerName)}</button>`:'—';};return state.archives.length?`<div class="table-wrap"><table><thead><tr><th>Year</th><th>World #1</th><th>Tour</th><th>Giro</th><th>Vuelta</th><th>Top team</th><th>Most wins</th><th>Most stages</th></tr></thead><tbody>${[...state.archives].reverse().map(a=>`<tr><td class="rank">${a.year}</td><td>${riderLink(a.summary.topRider)}</td><td>${gt(a,'tour')}</td><td>${gt(a,'giro')}</td><td>${gt(a,'vuelta')}</td><td>${a.summary.topTeam?.id?`<button class="entity-link" data-open-team="${a.summary.topTeam.id}">${esc(a.summary.topTeam.name)}</button>`:esc(a.summary.topTeam?.name||'—')}</td><td>${riderLink(a.summary.mostWins)} (${a.summary.mostWins?.raceWins||0})</td><td>${riderLink(a.summary.mostStages)} (${a.summary.mostStages?.stageWins||0})</td></tr>`).join('')}</tbody></table></div>`:'<article class="card"><h3>No seasons archived</h3><p class="muted">Finish the first year to open the historical table.</p></article>';}


function hallPage(){const eligible=state.riders.filter(r=>r.career.seasonCount>0||r.retired);if(!eligible.length)return `${pageHead('The short list of immortals','Hall of Fame','The Hall of Fame is a composition of short lists, not an exhaustive table.')}<article class="card"><h3>The hall opens after season one</h3><p class="muted">Greatness requires official history.</p></article>`;const top=hallOfFame(state,10),teams=[...state.teams].sort((a,b)=>teamHallScore(b)-teamHallScore(a)).slice(0,5);return `${pageHead('The short list of immortals','Hall of Fame','Weighted achievements create the overall top ten; specialist lists recognize riders whose careers were built on a particular stage profile.')}
<section class="hof-banner"><span>Greatest riders ever</span><h3>${top[0]?esc(top[0].name):'The hall awaits'}</h3><p>Grand Tours, Monuments, championships, stage wins, jerseys and longevity.</p></section>${hofRiderTable(top)}<article class="hof-method"><strong>Legacy balance</strong><span>The Tour carries the greatest weight, followed by the Giro and Vuelta. Roughly five Monument victories equal a Tour–Giro double; stages and lesser races add depth but cannot replace major championships.</span></article>
<div class="section-title"><h3>Specialist wings</h3><span>Top five by profile</span></div><div class="grid cols-3 specialist-grid">${['rouleur','puncheur','time-trialist','climber'].map(profile=>specialistList(profile)).join('')}</div>
<div class="section-title"><h3>Greatest teams</h3><span>Top five organizations</span></div><div class="grid cols-5 hof-team-grid">${teams.map((t,i)=>`<button class="hof-team" data-open-team="${t.id}"><span class="rank">${i+1}</span>${countryFlag(t.nationality)}<h4>${esc(t.identity)}</h4><p>${t.career.grandTours} GT · ${t.career.monuments} monuments</p><strong>${formatNumber(teamHallScore(t))}</strong></button>`).join('')}</div>`;}
function hofRiderTable(riders){return `<div class="table-wrap"><table><thead><tr><th>#</th><th>Rider</th><th>Active years</th><th>Grand Tours</th><th>Monuments</th><th>Week-long</th><th>Race wins</th><th>Stages</th><th>Score</th></tr></thead><tbody>${riders.map((r,i)=>`<tr><td class="rank">${i+1}</td><td><button class="entity-link" data-open-rider="${r.id}">${countryFlag(r.nationality)} ${esc(r.name)}</button></td><td>${r.career.seasonCount}</td><td>${r.career.grandTours}</td><td>${r.career.monuments}</td><td>${r.career.weeklong}</td><td>${r.career.raceWins}</td><td>${r.career.stageWins}</td><td><strong>${formatNumber(r.hallScore)}</strong></td></tr>`).join('')}</tbody></table></div>`;}
function specialistList(profile){const riders=state.riders.filter(r=>(r.career.seasonCount>0||r.retired)&&r.terrain===profile).sort((a,b)=>hallScore(b)-hallScore(a)).slice(0,5);return `<section class="card specialist-card"><div class="profile-mark ${profile==='time-trialist'?'time-trial':profile==='rouleur'?'flat':profile==='climber'?'mountain':profile==='cobbles'?'cobbles':'hilly'}"></div><h3>${titleCase(profile)}</h3>${riders.map((r,i)=>`<button class="record-row" data-open-rider="${r.id}"><span class="rank">${i+1}</span><span>${countryFlag(r.nationality)} <strong>${esc(r.name)}</strong></span><b>${formatNumber(hallScore(r))}</b></button>`).join('')||'<p class="muted">No inductees.</p>'}</section>`;}

function settingsPage(){return `${pageHead('Archive management','Save & Settings','The simulation remains local in IndexedDB for this development version. Export the complete universe as JSON whenever you want an external backup.')}
<div class="grid cols-2"><section class="card"><h3>Current archive</h3><p><strong>${esc(state.name)}</strong><br>Drawer ${slot} · Season ${state.year} · Week ${Math.ceil(state.currentDay/7)}</p><div class="top-actions"><button class="btn" data-action="save-now">Save now</button><button class="btn secondary" data-action="export">Export JSON</button><button class="btn secondary" data-action="back-slots">Return to drawers</button></div></section><section class="card"><h3>World scale</h3><p>${state.teams.filter(t=>t.status==='active'&&t.tier==='worldtour').length} WorldTeams · ${state.teams.filter(t=>t.status==='active'&&t.tier==='proseries').length} ProTeams · ${state.teams.filter(t=>t.status==='active'&&t.tier==='u23').length} U23 programs · ${state.teams.filter(t=>t.status==='active'&&t.tier==='continental').length} lightweight continental teams.</p><p>${formatNumber(state.riders.length)} rider records · ${formatNumber(state.directors.length)} director records · ${state.events.length} races.</p><p class="muted">New universes are fully procedural. Saves created in v0.1 retain their original riders when upgraded.</p></section></div>`;}

function renderModal(){if(modal.type==='rider')return riderModal(riderById(state,modal.id));if(modal.type==='team')return teamModal(teamById(state,modal.id));if(modal.type==='director')return directorModal(directorById(state,modal.id));return'';}
function modalShell(title,body){return `<div class="modal-backdrop"><section class="modal"><header class="modal-head"><h3>${title}</h3><button data-close-modal>×</button></header><div class="modal-body">${body}</div></section></div>`;}
function riderModal(r){if(!r)return'';return modalShell('Rider career dossier',riderProfileContent(r,false));}
function honor(label,value){return `<div><span>${label}</span><strong>${value}</strong></div>`;}
function stageProfileBreakdown(values){const max=Math.max(1,...Object.values(values||{}));return Object.entries(values||{}).map(([profile,value])=>`<div class="profile-stat"><span class="profile-mark ${profile}">${STAGE_LABELS[profile]}</span><i><b style="width:${value/max*100}%"></b></i><strong>${value}</strong></div>`).join('');}
function teamModal(t){if(!t)return'';return modalShell('Team organization & lineage',teamProfileContent(t,false));}
function honorCard(label,value,small){return `<article class="card flat kpi"><span>${label}</span><strong>${value}</strong><small>${esc(small)}</small></article>`;}
function directorModal(d){if(!d)return'';return modalShell('Race director dossier',directorProfileContent(d,false));}

function tierOptions(includeNational=true,selected=''){return [['worldtour','WorldTour'],['proseries','ProSeries'],['continental','Continental'],['u23','U23'],...(includeNational?[['national','Championships']]:[])].map(([v,l])=>`<option value="${v}" ${selected===v?'selected':''}>${l}</option>`).join('');}
function typeOptions(selected=''){return [['grand-tour','Grand Tours'],['monument','Monuments'],['stage-race','Stage races'],['classic','Classics'],['championship','Championships']].map(([v,l])=>`<option value="${v}" ${selected===v?'selected':''}>${l}</option>`).join('');}
function eventFavorites(event,limit=5){return state.riders.filter(r=>!r.retired&&r.targetEvents.includes(event.id)&&((event.tier==='u23'&&r.age<=22)||(event.tier!=='u23'))).sort((a,b)=>currentAbility(b)-currentAbility(a)).slice(0,limit);}

if(app){
app.addEventListener('click',async event=>{
  const target=event.target.closest('button,[data-route],[data-open-rider],[data-open-rider-page],[data-open-team],[data-open-team-page],[data-open-director],[data-open-director-page],[data-open-race],[data-close-modal]');if(!target)return;
  if(target.dataset.loadSlot){await openSlot(Number(target.dataset.loadSlot));return;}if(target.dataset.newSlot){await newSlot(Number(target.dataset.newSlot));return;}if(target.dataset.deleteSlot){if(confirm('Delete this entire cycling universe?')){await deleteUniverse(Number(target.dataset.deleteSlot));renderSaveScreen(await listUniverses());}return;}
  if(target.dataset.route){navigationStack=[];route=target.dataset.route;modal=null;render();return;}if(target.dataset.rankingScope){rankingScope=target.dataset.rankingScope;render();return;}if(target.dataset.menu!==undefined){document.querySelector('#sidebar')?.classList.toggle('open');return;}
  if(target.dataset.selectResult){selectedEventId=target.dataset.selectResult;render();return;}if(target.dataset.openRace){navigateDetail('race-detail','race',target.dataset.openRace);return;}
  if(target.dataset.openRiderPage||target.dataset.openRider){navigateDetail('rider-detail','rider',target.dataset.openRiderPage||target.dataset.openRider,'rider','overview');return;}if(target.dataset.openTeamPage||target.dataset.openTeam){navigateDetail('team-detail','team',target.dataset.openTeamPage||target.dataset.openTeam,'team','overview');return;}if(target.dataset.openDirectorPage||target.dataset.openDirector){navigateDetail('director-detail','director',target.dataset.openDirectorPage||target.dataset.openDirector,'director','overview');return;}if(target.dataset.closeModal!==undefined){modal=null;render();return;}
  if(target.dataset.riderTab){riderTab=target.dataset.riderTab;render();return;}if(target.dataset.teamTab){teamTab=target.dataset.teamTab;render();return;}if(target.dataset.directorTab){directorTab=target.dataset.directorTab;render();return;}if(target.dataset.magTab){magazineTab=target.dataset.magTab;render();return;}if(target.dataset.almanacTab){almanacTab=target.dataset.almanacTab;render();return;}if(target.dataset.statsEntity){statsEntity=target.dataset.statsEntity;render();return;}
  const action=target.dataset.action;if(action==='nav-back'){restoreNavigation();return;}if(!action||busy)return;
  if(action==='simulate-1'||action==='simulate-4'){busy=true;const weeks=action==='simulate-1'?1:4,year=state.year;const output=simulateWeeks(state,weeks);if(output.results.length)selectedEventId=output.results.at(-1).eventId;await persist();busy=false;render();toast(output.seasonComplete?`Season ${year} completed. Results remain open until you start the next season.`:`${weeks} week${weeks===1?'':'s'} simulated · ${output.results.length} race${output.results.length===1?'':'s'} completed.`);}
  if(action==='simulate-season'){if(!confirm(`Simulate the remainder of ${state.year}?`))return;busy=true;renderLoading();const year=state.year,output=simulateSeason(state);await persist();busy=false;selectedEventId=output.results.at(-1)?.eventId||latestResult()?.eventId;render();toast(`Season ${year} completed · results remain open until you start ${year+1}.`);}
  if(action==='open-next-season'){busy=true;renderLoading();const oldYear=state.year,stayRoute=route;openNextSeason(state);await persist();busy=false;route=['rider-detail','team-detail','director-detail','race-detail'].includes(stayRoute)?'results':stayRoute;selectedEventId=state.events[0]?.id;render();toast(`${oldYear} archived · ${state.year} season opened.`);}if(action==='save-now'){await persist();toast('Chronicle saved.');}if(action==='back-slots'){await persist();state=null;slot=null;renderSaveScreen(await listUniverses());}if(action==='export'){const blob=new Blob([JSON.stringify(state)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`peloton-chronicle-${state.year}.json`;anchor.click();URL.revokeObjectURL(url);}
});
app.addEventListener('click',event=>{if(event.target.classList.contains('modal-backdrop')){modal=null;render();}});
app.addEventListener('input',event=>{const id=event.target.id;if(id==='results-search'){resultsSearch=event.target.value;render();return;}if(id==='calendar-search'){calendarSearch=event.target.value;render();return;}if(id==='rider-search'){riderSearch=event.target.value;render();return;}if(id==='team-search'){teamSearch=event.target.value;render();return;}if(id==='director-search'){directorSearch=event.target.value;render();return;}if(id.startsWith('races-'))filterGroup('race-card-list','race-card','races');});
app.addEventListener('change',event=>{const id=event.target.id;if(id==='results-tier'){resultsTier=event.target.value;render();return;}if(id==='results-type'){resultsType=event.target.value;render();return;}if(id==='results-search'){resultsSearch=event.target.value;render();return;}if(id==='calendar-tier'){calendarTier=event.target.value;render();return;}if(id==='calendar-type'){calendarType=event.target.value;render();return;}if(id==='calendar-search'){calendarSearch=event.target.value;render();return;}if(id==='rider-tier'){riderTier=event.target.value;render();return;}if(id==='rider-rarity'){riderRarity=event.target.value;render();return;}if(id==='rider-program'){riderProgram=event.target.value;render();return;}if(id==='rider-terrain'){riderTerrain=event.target.value;render();return;}if(id==='team-tier'){teamTier=event.target.value;render();return;}if(id==='team-sort'){teamSort=event.target.value;render();return;}if(id==='director-tier'){directorTierFilter=event.target.value;render();return;}if(id.startsWith('races-'))filterGroup('race-card-list','race-card','races');if(id==='stats-scope'){statsScope=event.target.value;render();return;}if(id==='stats-metric'){statsMetric=event.target.value;render();return;}if(id==='stats-tier'){statsTier=event.target.value;render();return;}if(id==='ranking-tier'){rankingTier=event.target.value;render();return;}});
}
function filterGroup(containerId,itemClass,prefix){const tier=document.querySelector(`#${prefix}-tier`)?.value||'all',type=document.querySelector(`#${prefix}-type`)?.value||'all',q=document.querySelector(`#${prefix}-search`)?.value.toLowerCase()||'';document.querySelectorAll(`#${containerId} .${itemClass}`).forEach(row=>row.hidden=!((tier==='all'||row.dataset.tier===tier)&&(type==='all'||row.dataset.type===type)&&(row.dataset.search||'').includes(q)));}
function filterPeople(type){const q=document.querySelector(`#${type}-search`)?.value.toLowerCase()||'',tier=document.querySelector(`#${type}-tier`)?.value||'all',program=document.querySelector('#rider-program')?.value||'all',terrain=document.querySelector('#rider-terrain')?.value||'all',selector=type==='rider'?'.rider-card':type==='team'?'.team-card':'.director-card';document.querySelectorAll(selector).forEach(card=>card.hidden=!((card.dataset.search||'').includes(q)&&(tier==='all'||card.dataset.tier===tier)&&(type!=='rider'||program==='all'||card.dataset.program===program)&&(type!=='rider'||terrain==='all'||card.dataset.terrain===terrain)));}
